window.drawLucky=()=>{if(luckyTimer)return;let list=eligibleLucky();let exclude=(q('#excludeText').value||'').toLowerCase().split(',').map(x=>x.trim()).filter(Boolean);list=list.filter(p=>!exclude.some(x=>p.fullName.toLowerCase().includes(x)||p.phone.includes(x)));let count=q('#drawMode').value==='single'?1:Math.max(1,Math.min(Number(q('#winnerCount').value||1),50));if(!list.length)return toast('Không còn người đủ điều kiện quay');count=Math.min(count,list.length);let sec=Math.max(1,Number(q('#drawSeconds').value||5)),start=Date.now();startDefaultLuckyMusic();q('.slot').classList.add('celebrate');luckyTimer=setInterval(()=>{let p=list[Math.floor(Math.random()*list.length)];q('#slotName').textContent=p.fullName;q('#slotMeta').textContent=`${p.role} • ${p.chapter} • ${maskPhone(p.phone)}`;if(Date.now()-start>=sec*1000){clearInterval(luckyTimer);luckyTimer=null;let picked=[];let pool=[...list];for(let i=0;i<count;i++){let ix=Math.floor(Math.random()*pool.length);picked.push(pool.splice(ix,1)[0])}for(let p of picked)S.lucky.winners.push({id:uid('WIN'),meetingId:activeMeeting().id,personKey:p.personKey,fullName:p.fullName,phone:p.phone,role:p.role,chapter:p.chapter,company:p.company||'',wonAt:iso()});save();let main=picked[0];q('#slotName').textContent=count===1?main.fullName:`${count} NGƯỜI TRÚNG`;q('#slotMeta').textContent=count===1?`${main.role} • ${main.chapter} • ${maskPhone(main.phone)}`:picked.map(x=>x.fullName).join(' • ');renderLucky();log('Lucky Draw','Winner',picked.map(x=>x.fullName).join(', '));setTimeout(()=>q('.slot')?.classList.remove('celebrate'),1500)}},80)};
window.removeLuckyWinner=key=>{if(!S.lucky.removedIds.includes(key))S.lucky.removedIds.push(key);save();renderLucky();toast('Đã loại người này khỏi các lượt quay tiếp')};
window.resetLucky=()=>{if(!confirm('Làm mới kết quả Lucky Draw của buổi họp hiện tại?'))return;let mid=activeMeeting().id;S.lucky.winners=S.lucky.winners.filter(w=>w.meetingId!==mid);S.lucky.removedIds=[];save();renderLucky();q('#slotName').textContent='Sẵn sàng quay';q('#slotMeta').textContent='Danh sách lấy từ điểm danh, đã khử trùng'};
window.exportReportCsv=()=>{if(!requireAuth())return;let rows=[['LOAI','HO TEN','DOANH NGHIEP','NGANH NGHE','TRANG THAI'],...S.members.map(m=>['HOI VIEN',m.fullName,m.company,m.industry,m.status]),[],['CO HOI','NGUOI TRAO','NGUOI NHAN','LOAI','GIA TRI','TRANG THAI'],...S.opportunities.map(o=>['CO HOI',(o.giverName||memberName(o.giverId)),o.receiverName,o.type,o.value,o.status]),[],['TAI CHINH','MA PHIEU','DANH MUC','NOI DUNG','SO TIEN','TRANG THAI'],...S.finance.map(f=>['TAI CHINH',f.id,f.category,f.description,(f.kind==='income'?f.amount:-f.amount),f.status])];let csv='\ufeff'+rows.map(r=>r.map(v=>`"${String(v??'').replace(/"/g,'""')}"`).join(',')).join('\n'),blob=new Blob([csv],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`VBNA_Chapter11_Report_${new Date().toISOString().slice(0,10)}.csv`;document.body.append(a);a.click();a.remove();URL.revokeObjectURL(url);log('Xuất báo cáo','Report','CSV tổng hợp')};
