const clockVN=d=>new Date(d).toLocaleTimeString('vi-VN',{timeZone:'Asia/Ho_Chi_Minh',hour:'2-digit',minute:'2-digit',hour12:false});
const sum=(xs,key)=>xs.reduce((a,x)=>a+Number(x[key]||0),0);
