 q('#departmentMenu').innerHTML=S.departments.map(d=>`<a class="side-link ${d.id===dep.id?'active':''}" href="departments.html?dep=${d.id}">${esc(d.name)}</a>`).join('');q('#departmentName').textContent=dep.name;q('#departmentScope').textContent=S.config.term.name;
