const HERO_DEFAULT='assets/chapter-networking.png';
const heroDefaults={desktop:{x:50,y:45,zoom:100,height:560},mobile:{x:65,y:40,zoom:100,height:340}};
const heroClamp=(v,min,max,fallback)=>Number.isFinite(Number(v))?Math.max(min,Math.min(max,Number(v))):fallback;
function heroLayout(raw={}){return Object.fromEntries(['desktop','mobile'].map(mode=>{const d=heroDefaults[mode],s=raw?.[mode]||{};return [mode,{x:heroClamp(s.x,0,100,d.x),y:heroClamp(s.y,0,100,d.y),zoom:heroClamp(s.zoom,100,250,d.zoom),height:heroClamp(s.height,mode==='desktop'?460:240,mode==='desktop'?800:520,d.height)}]}))}
function heroSource(src){return imageSrc(src)||HERO_DEFAULT}
function positionHeroPhoto(frame,layout){const im=frame?.querySelector('img');if(!im||!im.naturalWidth||!frame.clientWidth)return;const scale=Math.max(frame.clientWidth/im.naturalWidth,frame.clientHeight/im.naturalHeight)*layout.zoom/100;const w=im.naturalWidth*scale,h=im.naturalHeight*scale;Object.assign(im.style,{width:w+'px',height:h+'px',left:-(w-frame.clientWidth)*layout.x/100+'px',top:-(h-frame.clientHeight)*layout.y/100+'px'});}
let publicHeroObserver;
function mountPrestigeHero(){const old=q('.landing-hero');if(!old)return;const c=S.config.site,copy=old.querySelector('.landing-copy'),meeting=old.querySelector('.meeting-float'),bottom=copy.querySelector('.hero-bottom');const bar=document.createElement('div');bar.className='prestige-meetingbar container';if(bottom)bar.append(bottom);if(meeting)bar.append(meeting);old.className='landing-hero prestige-hero';old.innerHTML=`<div class="hero-photo-stage" aria-hidden="true"><img alt="" src="${esc(heroSource(c.heroImage))}"></div><div class="prestige-hero-shade"></div><div class="container prestige-hero-content"></div>`;old.querySelector('.prestige-hero-content').append(copy);old.after(bar);const frame=old.querySelector('.hero-photo-stage'),im=frame.querySelector('img'),layout=heroLayout(c.heroLayout);const update=()=>{const mobile=window.innerWidth<=800;old.style.setProperty('--hero-desktop-height',layout.desktop.height+'px');old.style.setProperty('--hero-mobile-height',layout.mobile.height+'px');positionHeroPhoto(frame,layout[mobile?'mobile':'desktop']);};im.addEventListener('load',update);publicHeroObserver?.disconnect();publicHeroObserver=new ResizeObserver(update);publicHeroObserver.observe(frame);update();}
const homeBeforePrestige=renderHomeV6;
renderHomeV6=function(){homeBeforePrestige();document.body.classList.add('prestige-public');mountPrestigeHero()};
leaderCard=function(name,title,photo,featured=false){return `<article class="leader-card ${featured?'featured':''}"><div class="prestige-portrait">${portrait(name,photo)}</div><div class="prestige-nameplate"><h3>${esc(name||'Đang cập nhật')}</h3><p>${esc(title)}</p></div></article>`};
const directoryBeforePrestige=window.filterDirectory;
window.filterDirectory=function(){directoryBeforePrestige();qa('.directory-card').forEach(card=>{const photo=card.querySelector('.directory-top .portrait');if(!photo)return;const frame=document.createElement('div');frame.className='prestige-member-photo';frame.append(photo);card.prepend(frame)});};
const membersBeforePrestige=renderMembersV6;
renderMembersV6=function(){membersBeforePrestige();document.body.classList.add('prestige-public')};
const mediaBeforePrestige=renderMedia;
renderMedia=function(){mediaBeforePrestige();document.body.classList.add('prestige-public')};
let heroDraft=null,heroEditorObserver,heroUploadSequence=0;
const canEditHero=()=>canLead()||canDept('events');
const settingsBeforePrestige=renderSiteSettings;
renderSiteSettings=function(){settingsBeforePrestige();if(!canEditHero())return;heroDraft={image:S.config.site.heroImage||'',layout:heroLayout(S.config.site.heroLayout),mode:'desktop',loading:false};heroUploadSequence++;q('#siteHero')?.closest('.field')?.remove();const anchor=q('.report-page .panel');anchor?.insertAdjacentHTML('afterend',`<section class="panel hero-editor" id="hero-image-editor"><div class="toolbar"><div><span class="eyebrow">TRANG CHỦ</span><h2>Ảnh lớn đầu trang</h2><p class="small-text">Thay ảnh, phóng to và kéo ảnh để chọn góc hiển thị. Bố cục máy tính và điện thoại được lưu riêng.</p></div><a class="btn btn-outline" href="index.html" target="_blank" rel="noopener">Xem trang chủ ↗</a></div><div class="hero-editor-grid"><div><div class="hero-editor-tabs" role="group" aria-label="Chế độ xem trước"><button type="button" class="btn btn-wine" data-hero-mode="desktop" onclick="switchHeroMode('desktop')" aria-pressed="true">Máy tính</button><button type="button" class="btn btn-outline" data-hero-mode="mobile" onclick="switchHeroMode('mobile')" aria-pressed="false">Điện thoại</button></div><div class="hero-preview-shell"><div id="heroPreview" class="hero-composition-preview" tabindex="0" role="group" aria-label="Kéo để di chuyển ảnh; dùng các phím mũi tên để căn ảnh" aria-describedby="heroEditorHelp"><div class="hero-photo-stage"><img alt="Ảnh xem trước trang chủ" src="${esc(heroSource(heroDraft.image))}" draggable="false"></div><div class="hero-preview-shade"></div><div class="hero-preview-copy"><strong>${esc(S.config.site.slogan).split('\n').join('<br>')}</strong><p>${esc(S.config.site.subtitle)}</p><span>Trở thành khách mời →</span></div></div></div><p class="small-text" id="heroEditorHelp">Kéo trực tiếp trên ảnh hoặc dùng các thanh điều chỉnh. Khi ảnh đã vừa khung, tăng độ phóng để có thêm khoảng di chuyển.</p></div><div class="hero-editor-controls">${field('heroPhotoUpload','Thay ảnh JPG / PNG / WebP','','file','accept="image/png,image/jpeg,image/webp" onchange="uploadHeroDraft(event)"')}<p class="small-text">Tối đa 6 MB. Ưu tiên ảnh ngang có độ phân giải cao.</p>${[['zoom','Phóng to',100,250,1,'%'],['x','Vị trí ngang',0,100,1,'%'],['y','Vị trí dọc',0,100,1,'%'],['height','Chiều cao khung',460,800,10,'px']].map(([key,label,min,max,step,unit])=>`<div class="field hero-range"><label for="hero-${key}">${label} <output id="hero-${key}-value"></output></label><input id="hero-${key}" type="range" min="${min}" max="${max}" step="${step}" oninput="setHeroValue('${key}',this.value)" aria-describedby="heroEditorHelp"></div>`).join('')}<button class="btn btn-outline" type="button" onclick="resetHeroView()">Đặt lại góc ảnh</button><button class="btn btn-outline" type="button" onclick="useDefaultHero()">Dùng ảnh minh họa mặc định</button><p class="small-text">Ảnh mẫu là ảnh minh họa. Ảnh và cách căn được lưu trên trình duyệt đang sử dụng, theo cơ chế dữ liệu hiện tại của V6.</p></div></div><div class="form-actions"><button class="btn btn-wine" id="saveHeroButton" type="button" onclick="saveHeroComposition()">Lưu ảnh & cách hiển thị</button><button class="btn btn-outline" type="button" onclick="cancelHeroDraft()">Hủy thay đổi ảnh</button><span id="heroEditorStatus" role="status" aria-live="polite"></span></div></section>`);mountHeroEditor();};
function refreshHeroEditor(){if(!heroDraft)return;const box=q('#heroPreview');if(!box)return;const mode=heroDraft.mode,s=heroDraft.layout[mode];box.dataset.mode=mode;box.style.aspectRatio=mode==='desktop'?'1440 / '+s.height:'390 / '+s.height;box.style.width=mode==='desktop'?'100%':'min(390px, 100%)';for(const key of ['zoom','x','y','height']){const input=q('#hero-'+key);if(key==='height'){input.min=mode==='desktop'?460:240;input.max=mode==='desktop'?800:520}input.value=s[key];q('#hero-'+key+'-value').textContent=Math.round(s[key])+(key==='height'?' px':'%')};qa('[data-hero-mode]').forEach(b=>{const active=b.dataset.heroMode===mode;b.className='btn '+(active?'btn-wine':'btn-outline');b.setAttribute('aria-pressed',String(active))});q('#saveHeroButton').disabled=heroDraft.loading;positionHeroPhoto(box.querySelector('.hero-photo-stage'),s);}
function heroChanged(){q('#heroEditorStatus').textContent='Chưa lưu';refreshHeroEditor()}
window.switchHeroMode=mode=>{if(!heroDraft||!['desktop','mobile'].includes(mode))return;heroDraft.mode=mode;refreshHeroEditor()};
window.setHeroValue=(key,value)=>{if(!heroDraft||!['x','y','zoom','height'].includes(key))return;heroDraft.layout[heroDraft.mode][key]=Number(value);heroDraft.layout=heroLayout(heroDraft.layout);heroChanged()};
window.resetHeroView=()=>{if(!heroDraft)return;heroDraft.layout[heroDraft.mode]={...heroDefaults[heroDraft.mode]};heroChanged()};
window.useDefaultHero=()=>{if(!canEditHero()||!heroDraft)return;heroUploadSequence++;heroDraft.loading=false;heroDraft.image='';q('#heroPhotoUpload').value='';heroDraft.layout=heroLayout();q('#heroPreview img').src=HERO_DEFAULT;heroChanged()};
window.cancelHeroDraft=()=>{if(!heroDraft)return;heroUploadSequence++;heroDraft.loading=false;heroDraft.image=S.config.site.heroImage||'';heroDraft.layout=heroLayout(S.config.site.heroLayout);q('#heroPhotoUpload').value='';q('#heroPreview img').src=heroSource(heroDraft.image);q('#heroEditorStatus').textContent='Đã khôi phục bản đang lưu';refreshHeroEditor()};
window.uploadHeroDraft=async e=>{if(!canEditHero()||!heroDraft)return;const seq=++heroUploadSequence;if(!e.target.files?.length)return;heroDraft.loading=true;q('#heroEditorStatus').textContent='Đang đọc ảnh…';refreshHeroEditor();try{const src=await readImage(e.target);if(seq!==heroUploadSequence||!canEditHero()||!q('#heroPreview'))return;heroDraft.image=src;heroDraft.layout=heroLayout();q('#heroPreview img').src=src;q('#heroEditorStatus').textContent='Ảnh mới — chưa lưu'}catch(err){if(seq===heroUploadSequence){e.target.value='';q('#heroEditorStatus').textContent=err.message;toast(err.message)}}finally{if(seq===heroUploadSequence){heroDraft.loading=false;refreshHeroEditor()}}};
window.saveHeroComposition=()=>{if(!canEditHero()||!heroDraft||heroDraft.loading)return;const before=structuredClone(S.config.site);try{S.config.site.heroImage=heroDraft.image;S.config.site.heroLayout=heroLayout(heroDraft.layout);save();q('#heroEditorStatus').textContent='Đã lưu ảnh và bố cục cho máy tính / điện thoại';toast('Đã lưu ảnh trang chủ','success')}catch(err){S.config.site=before;q('#heroEditorStatus').textContent='Chưa lưu được ảnh. Vui lòng chọn ảnh nhỏ hơn hoặc kiểm tra dung lượng trình duyệt.';toast('Không đủ dung lượng lưu ảnh; bản trước vẫn được giữ')}};
function mountHeroEditor(){const box=q('#heroPreview'),frame=box.querySelector('.hero-photo-stage'),im=frame.querySelector('img');im.addEventListener('load',refreshHeroEditor);im.addEventListener('error',()=>{q('#heroEditorStatus').textContent='Không tải được ảnh. Vui lòng chọn ảnh khác.'});heroEditorObserver?.disconnect();heroEditorObserver=new ResizeObserver(refreshHeroEditor);heroEditorObserver.observe(box);let drag=null;
 box.addEventListener('pointerdown',e=>{if(e.button!==0||heroDraft.loading)return;const s=heroDraft.layout[heroDraft.mode];drag={id:e.pointerId,x:e.clientX,y:e.clientY,startX:s.x,startY:s.y,overflowX:im.getBoundingClientRect().width-frame.clientWidth,overflowY:im.getBoundingClientRect().height-frame.clientHeight};box.setPointerCapture(e.pointerId);box.classList.add('dragging');e.preventDefault()});
 box.addEventListener('pointermove',e=>{if(!drag||drag.id!==e.pointerId)return;const s=heroDraft.layout[heroDraft.mode];if(drag.overflowX>1)s.x=heroClamp(drag.startX-(e.clientX-drag.x)/drag.overflowX*100,0,100,s.x);if(drag.overflowY>1)s.y=heroClamp(drag.startY-(e.clientY-drag.y)/drag.overflowY*100,0,100,s.y);heroChanged()});
 const finish=()=>{drag=null;box.classList.remove('dragging')};box.addEventListener('pointerup',finish);box.addEventListener('pointercancel',finish);box.addEventListener('lostpointercapture',finish);
 box.addEventListener('keydown',e=>{const axes={ArrowLeft:['x',5],ArrowRight:['x',-5],ArrowUp:['y',5],ArrowDown:['y',-5]};if(!axes[e.key])return;e.preventDefault();const [axis,step]=axes[e.key],s=heroDraft.layout[heroDraft.mode];s[axis]=heroClamp(s[axis]+step*(e.shiftKey?2:1),0,100,s[axis]);heroChanged()});refreshHeroEditor();}

