const designOverview = [
 ['gioi-thieu','Giới thiệu VBNA','VBNA · VIETNAM BUSINESSMEN NETWORKING ASSOCIATION · TỔ CHỨC KẾT NỐI DOANH NHÂN VIỆT NAM. VBNA là tổ chức kết nối của các doanh nhân Hải Phòng, tự nguyện gia nhập với mục tiêu kết nối doanh nhân, gia tăng doanh số bán hàng, phát triển mối quan hệ và chia sẻ kiến thức kinh doanh.'],
 ['triet-ly','Mục đích & triết lý','Nối kết Doanh nhân – Nâng tầm Doanh nghiệp. Triết lý GIVER’S GAIN: CHO là NHẬN. Chia sẻ mối quan hệ, kiến thức, cơ hội kinh doanh và sự hỗ trợ. Quy trình “Success Referrals” sử dụng bộ công cụ có nguồn gốc từ Mỹ theo nội dung giới thiệu VBNA.'],
 ['su-menh','Sứ mệnh','Hỗ trợ các doanh nghiệp hội viên phát triển kinh doanh thông qua bộ quy trình và công cụ của VBNA để gia tăng doanh số bán hàng và mở rộng các mối quan hệ.'],
 ['san-pham','Sản phẩm dịch vụ','Số lượng và giá trị cơ hội giao dịch thành công cho hội viên; số lượng và chất lượng hội viên tham gia VBNA; số lượng khách mời tham gia buổi họp Chapter thường tuần.'],
 ['gia-tri','7 giá trị cốt lõi',['Hoạt động theo triết lý “Cho là nhận”. Hội viên trao cơ hội kinh doanh cho nhau trong các buổi họp thường tuần, đồng thời đón nhận những cơ hội từ các hội viên khác.','Phát triển kinh doanh thông qua mối quan hệ lâu dài, bền chặt và có ý nghĩa. Kết nối kinh doanh là nuôi dưỡng các mối quan hệ, bởi mọi người muốn làm kinh doanh với những người họ biết và tin tưởng.','Huấn luyện và đào tạo. Liên tục hoàn thiện kỹ năng phát triển bản thân, chuyên môn và nghiệp vụ. VBNA cung cấp những cơ hội đa dạng để hỗ trợ học tập suốt đời.','Kết hợp truyền thống và đổi mới để tạo thành công. Truyền thống cho biết nguồn gốc và đặt nền móng; đổi mới và sáng tạo giúp tổ chức tiếp tục phát triển.','Thái độ tích cực và hỗ trợ. Một môi trường với những doanh nhân luôn muốn giúp nhau thành công hơn.','Tính trách nhiệm. Một hệ thống kết nối cá nhân hiệu quả cần sự cam kết và trách nhiệm của mỗi hội viên.','Sự công nhận. Ghi nhận đóng góp của mọi hội viên VBNA.']],
 ['loi-ich','5 lợi ích hội viên',['Sở hữu một đội ngũ Marketing lớn mạnh.','Marketing độc quyền trong Chapter.','Nguồn cơ hội kinh doanh mới và liên tục.','Huấn luyện và đào tạo.','Mối quan hệ kinh doanh lâu dài và bền vững.']],
 ['tham-gia','Điều kiện tham gia & nhiệm vụ','Chủ doanh nghiệp, cổ đông, CEO… có sản phẩm, dịch vụ chất lượng; có trách nhiệm, uy tín, năng động, thích giao tiếp và tạo quan hệ. Hiện diện hàng tuần và cam kết 5 nhiệm vụ: mời tối thiểu 2 khách mời; Dance 1-2-1 với 4 hội viên khác; có tối thiểu 2 cơ hội; cảm ơn khi nhận cơ hội; chứng thực sau khi trao cơ hội.']
];
const designSteps=['Giao lưu mở (...trước 08:00 & 14:00)','Giới thiệu HĐTV, BLĐ & BĐH Chapter','Tổng quan về VBNA','Đào tạo kỹ năng Networking','Biểu dương khen ngợi','Trao đổi danh thiếp','Kết nạp, tái gia nhập hội viên','Giới thiệu ngành nghề của hội viên','Giới thiệu ngành nghề của Khách mời','Báo cáo của Tr. Ban Hội viên Chapter','Báo cáo của Ban Hội viên Chapter','Giới thiệu diễn giả tuần','Trình bày của Diễn giả của tuần','Trao & nhận Cơ hội','Báo cáo của Ban Thư ký/ Ngân quỹ','Thông báo của VBNA','Rút thăm trao quà tặng','Định hướng hội viên mới','Định hướng & lấy ý kiến khách mời','Kết thúc buổi họp'];
const designTabs=[['overview','Tổng quan'],['profile','Hồ sơ'],['opportunities','Cơ hội'],['finance','Tài chính'],['attendance','Điểm danh'],['notifications','Thông báo']];
const designURL=(page,id)=>page+'?id='+encodeURIComponent(id);
function publicPhone(value){const s=String(value||'').replace(/\D/g,'');if(s.length<7)return 'Chưa công khai';const start=Math.floor((s.length-3)/2);return s.slice(0,start)+'***'+s.slice(start+3)}
function designPhoto(m){const src=imageSrc(m.avatar);return src?`<img class="d-avatar" src="${esc(src)}" alt="${esc(m.fullName)}" loading="lazy">`:`<div class="d-avatar d-initials" aria-label="Chưa có ảnh đại diện">${esc((m.fullName||'HV').split(' ').filter(Boolean).slice(-2).map(n=>n[0]).join(''))}</div>`}
function designBrand(){const logo=imageSrc(S.config.site.leftLogo);return `<a class="d-brand" href="index.html" aria-label="VBNA Chapter 11 — Trang chủ">${logo?`<img src="${esc(logo)}" alt="Logo Chapter 11">`:'<strong>VBNA</strong><span>CHAPTER 11</span>'}</a>`}
function designDrop(id,label,items,caption){return `<div class="d-nav-item"><button class="d-nav-trigger" aria-expanded="false" aria-controls="menu-${id}" data-menu="${id}">${label}<span aria-hidden="true">⌄</span></button><div id="menu-${id}" class="d-dropdown" hidden><div class="d-menu-intro"><span class="d-eyebrow">CHAPTER 11</span><h3>${label}</h3><p>${caption}</p></div><div class="d-menu-links">${items.map(([href,text,sub])=>`<a href="${href}"><strong>${text}</strong>${sub?`<small>${sub}</small>`:''}<span aria-hidden="true">↗</span></a>`).join('')}</div></div></div>`}
publicHeader=function(){return `<a class="d-skip" href="#main">Đi tới nội dung</a><div class="d-top"><div class="d-wrap"><span>TỔ CHỨC KẾT NỐI DOANH NHÂN VIỆT NAM</span><a href="${currentUser()?'member-portal.html':'login.html'}">${currentUser()?'Không gian hội viên':'Đăng nhập hội viên'} →</a></div></div><header class="d-header"><div class="d-wrap d-nav">${designBrand()}<button class="d-mobile-toggle" aria-expanded="false" aria-controls="d-navigation">Menu <span aria-hidden="true">☰</span></button><nav id="d-navigation" aria-label="Điều hướng chính"><a class="d-home-link" href="index.html">Trang chủ</a>${designDrop('overview','Tổng quan VBNA',designOverview.map(([id,name])=>['about.html#'+id,name]),'Kết nối từ sự tin tưởng. Phát triển cùng cộng đồng.')}${designDrop('leadership','BĐH các nhiệm kỳ',[['leadership.html#founders','Giám đốc mở & Trưởng ban định hướng','Những người đặt nền móng'],...[7,6,5,4,3,2,1].map(n=>['leadership.html?term='+n,'Ban điều hành nhiệm kỳ '+n,(n<=2?7:n<=6?8:9)+' ban'])],'Tiếp nối những giá trị qua từng nhiệm kỳ.')}${designDrop('members','Hội viên',[['members.html','Danh sách hội viên','Tìm theo ngành nghề và Power Team'],['member-map.html','Bản đồ hội viên','Thông tin vị trí theo quyền công khai'],['member-portal.html','Không gian của tôi','Dành cho hội viên đã đăng nhập']],'Gặp gỡ những người cùng bạn phát triển.')}${designDrop('activities','Các hoạt động',[['media.html#video','Video','Câu chuyện và hoạt động kết nối'],['media.html#album','Album ảnh','Khoảnh khắc của Chapter 11']],'Lưu giữ những kết nối có ý nghĩa.')}<a href="meeting-process.html">20 bước buổi họp</a></nav><a class="d-button d-nav-cta" href="guest-register.html">Đăng ký khách mời</a></div></header>`};
publicFooter=function(){return `<footer class="d-footer"><div class="d-wrap"><div>${designBrand()}<p>Nối kết Doanh nhân · Nâng tầm Doanh nghiệp</p></div><div><a href="about.html">Tổng quan VBNA</a><a href="members.html">Hội viên</a><a href="media.html">Các hoạt động</a><a href="support.html">Hỗ trợ hội viên</a></div><span>vbnachapter11.com</span></div><div class="d-wrap d-footer-note">Bản chạy thử · Dữ liệu trên trình duyệt này · Ảnh bìa minh họa</div></footer>`};
function designMount(content,kind=''){designEvents.abort();designEvents=new AbortController();document.body.className='design-page '+kind;document.body.innerHTML=publicHeader()+`<main id="main">${content}</main>`+publicFooter();bindDesignMenus();const titles={'home':'Nối kết Doanh nhân','members-public':'Danh sách hội viên','member-profile':'Hồ sơ hội viên','member-portal':'Không gian hội viên','about-public':'Tổng quan VBNA','leadership-public':'BĐH các nhiệm kỳ','meeting-process':'20 bước buổi họp','member-map':'Bản đồ hội viên','meeting-summary':'Báo cáo sơ bộ','media':'Các hoạt động'};document.title=(titles[document.body.dataset.page]||'VBNA')+' · Chapter 11'}
function bindDesignMenus(){
 const currentPage=location.pathname.split('/').pop()||'index.html';
 qa('#d-navigation>a').forEach(a=>{if(a.getAttribute('href')?.split(/[?#]/)[0]===currentPage)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});
 qa('.d-nav-item').forEach(item=>{const active=Array.from(item.querySelectorAll('.d-dropdown a')).some(a=>a.getAttribute('href')?.split(/[?#]/)[0]===currentPage);item.querySelector('[data-menu]')?.setAttribute('data-current',String(active))});
 const buttons=qa('[data-menu]');
 function close(except,focus=false){buttons.forEach(b=>{if(b!==except){const was=b.getAttribute('aria-expanded')==='true';b.setAttribute('aria-expanded','false');q('#'+b.getAttribute('aria-controls')).hidden=true;if(focus&&was)b.focus()}})}
 buttons.forEach(b=>b.addEventListener('click',()=>{const open=b.getAttribute('aria-expanded')==='true';close(b);b.setAttribute('aria-expanded',String(!open));q('#'+b.getAttribute('aria-controls')).hidden=open}));
 q('.d-header').addEventListener('keydown',e=>{if(e.key==='Escape'){close(null,true);const mobile=q('.d-mobile-toggle');if(mobile.getAttribute('aria-expanded')==='true'){mobile.setAttribute('aria-expanded','false');q('#d-navigation').classList.remove('is-open');mobile.focus()}}});
 q('.d-header').addEventListener('focusout',()=>setTimeout(()=>{if(!q('.d-header')?.contains(document.activeElement))close()},0));
 document.addEventListener('click',e=>{if(!e.target.closest('.d-header'))close()},{signal:designEvents.signal});
 q('.d-mobile-toggle').addEventListener('click',e=>{const b=e.currentTarget,open=b.getAttribute('aria-expanded')!=='true';b.setAttribute('aria-expanded',String(open));q('#d-navigation').classList.toggle('is-open',open);if(!open)close()});
 q('#d-navigation').addEventListener('click',e=>{if(e.target.closest('a')){close();q('.d-mobile-toggle').setAttribute('aria-expanded','false');q('#d-navigation').classList.remove('is-open')}});
}
let designEvents=new AbortController();
function designMeeting(){const all=S.meetings.filter(m=>m.date&&m.status!=='cancelled').slice().sort((a,b)=>(a.date+(a.time||'')).localeCompare(b.date+(b.time||'')));return all.find(m=>m.date>=localDay())||all.at(-1)||null}
function meetingHref(page,m=designMeeting()){return page+(m?'?meeting='+encodeURIComponent(m.id):'')}
function designMeetingCard(){const m=designMeeting();return `<section class="d-meeting d-wrap" aria-label="Buổi họp gần nhất"><div><span class="d-eyebrow">BUỔI HỌP GẦN NHẤT</span><h2>${esc(m?.name||'Kết nối kinh doanh thường tuần')}</h2><small>${m?(m.date<localDay()?'Buổi họp đã diễn ra':m.status==='open'?'Đang mở':'Sắp diễn ra'):'Chưa có lịch mới'}</small></div><dl><div><dt>Thời gian</dt><dd>${m?fmtDate(m.date)+' · '+esc(m.time||'Đang cập nhật'):'Đang cập nhật'}</dd></div><div><dt>Địa điểm</dt><dd>${esc(m?.location||'Đang cập nhật')}</dd></div><div><dt>Diễn giả</dt><dd>${esc(m?.speaker||'Đang cập nhật')}</dd></div></dl>${m?`<a class="d-link" href="${meetingHref('meeting.html',m)}">Xem buổi họp →</a>`:'<a class="d-link" href="guest-register.html">Đăng ký quan tâm →</a>'}</section>`}
function designActions(){return `<div class="d-quick d-wrap">${[['01','Đăng ký khách mời','Tham gia cùng chúng tôi','guest-register.html'],['02','Điểm danh','Xác nhận tham dự','checkin.html'],['03','Trao cơ hội','Kết nối kinh doanh','opportunity.html'],['04','Báo cáo sơ bộ','Tổng kết buổi họp','meeting-summary.html']].map(([n,title,sub,url])=>`<a href="${meetingHref(url)}"><span>${n}</span><div><strong>${title}</strong><small>${sub}</small></div><b aria-hidden="true">↗</b></a>`).join('')}</div>`}
memberCardV6=function(m){return `<article class="d-member-card v7-person-card">${designPhoto(m)}<div class="v7-person-info"><h3><a href="${designURL('member-profile.html',m.id)}">${esc(m.fullName)}</a></h3><p class="v7-person-title">${esc(m.title||'Hội viên Chapter 11')}</p><p class="v7-person-company">${esc(m.company||'Doanh nghiệp đang cập nhật')}</p><a class="d-link" href="${designURL('member-profile.html',m.id)}" aria-label="Xem hồ sơ ${esc(m.fullName)}">Xem hồ sơ chi tiết →</a></div></article>`};
function designTermTabs(n,home=false){return `<div class="d-term-tabs" aria-label="Chọn nhiệm kỳ">${[7,6,5,4,3,2,1].map(t=>home?`<button type="button" aria-pressed="${t===n}" data-term="${t}">Nhiệm kỳ ${t}</button>`:`<a ${t===n?'aria-current="page"':''} href="leadership.html?term=${t}">Nhiệm kỳ ${t}</a>`).join('')}</div>`}
function designTermCard(n){return `<img src="${esc(heroSource(S.config.site.heroImage))}" alt="Ảnh minh họa kết nối doanh nhân" loading="lazy"><div><span class="d-eyebrow">TIẾP NỐI NHỮNG GIÁ TRỊ</span><h3>Ban điều hành nhiệm kỳ ${n} <small>${n<=2?7:n<=6?8:9} ban</small></h3><p>Đồng hành cùng cộng đồng doanh nhân Chapter 11.</p><a href="leadership.html#founders">Giám đốc mở & Trưởng ban định hướng →</a></div><a class="d-button" href="leadership.html?term=${n}">Xem cơ cấu điều hành →</a>`}
function designMediaTeaser(kind='video'){const items=S.media.filter(m=>m.kind===kind);return items.length?items.slice(0,3).map(m=>`<a class="d-media-card" href="media.html#${kind}">${imageSrc(m.images?.[0])?`<img src="${esc(imageSrc(m.images[0]))}" alt="${esc(m.title)}" loading="lazy">`:`<div class="d-media-placeholder">${kind==='video'?'▷':'▧'}</div>`}<h3>${esc(m.title)}</h3><p>${esc(m.description||'')}</p></a>`).join(''):`<div class="d-media-empty"><span aria-hidden="true">${kind==='video'?'▷':'▧'}</span><div><h3>${kind==='video'?'Video kết nối doanh nhân':'Album khoảnh khắc Chapter 11'}</h3><p>${kind==='video'?'Video':'Album ảnh'} sẽ xuất hiện tại đây khi được cập nhật.</p><a class="d-link" href="media.html#${kind}">Mở thư viện →</a></div></div>`}
renderHomeV6=function(){
 designMount(`<section class="d-hero"><div class="d-hero-copy"><span class="d-eyebrow">VBNA CHAPTER 11</span><h1>Nối kết Doanh nhân<br>Nâng tầm Doanh nghiệp</h1><p>Kết nối. Chia sẻ. Cùng phát triển.</p><div><a class="d-button d-cream" href="${meetingHref('guest-register.html')}">Đăng ký tham gia buổi họp</a><a href="about.html">Khám phá VBNA →</a></div><small>CỘNG ĐỒNG DOANH NHÂN<br>VÌ MỘT VIỆT NAM THỊNH VƯỢNG</small></div><div class="d-hero-photo"><img src="${esc(heroSource(S.config.site.heroImage))}" alt="Ảnh minh họa doanh nhân kết nối tại Chapter 11"><span>Hình ảnh minh họa</span></div></section>${designMeetingCard()}${designActions()}
 <section class="d-section d-tint" id="about"><div class="d-wrap d-overview"><div><span class="d-eyebrow">TỔNG QUAN VỀ VBNA</span><h2>Cho là nhận</h2><p>Phát triển kinh doanh từ những mối quan hệ bền vững.</p><a class="d-link" href="about.html">Tìm hiểu về VBNA →</a></div>${[['Sứ mệnh','Hỗ trợ hội viên gia tăng doanh số và mở rộng các mối quan hệ.','su-menh'],['7 giá trị cốt lõi','Cho là nhận. Quan hệ bền vững. Đào tạo. Đổi mới. Tích cực. Trách nhiệm. Sự công nhận.','gia-tri'],['5 lợi ích hội viên','Marketing lớn mạnh và độc quyền. Cơ hội mới. Đào tạo. Quan hệ bền vững.','loi-ich']].map(([title,text,id],i)=>`<a href="about.html#${id}"><span class="d-value-index">0${i+1}</span><h3>${title}</h3><p>${text}</p></a>`).join('')}</div></section>
 <section class="d-section" id="leadership"><div class="d-wrap"><div class="d-section-head"><div><h2>BĐH các nhiệm kỳ</h2><p>Tiếp nối những giá trị</p></div>${designTermTabs(7,true)}</div><div id="d-term-card" class="d-term-card">${designTermCard(7)}</div></div></section>
 <section class="d-section d-tint" id="community"><div class="d-wrap"><div class="d-section-head"><div><span class="d-eyebrow">CỘNG ĐỒNG DOANH NHÂN</span><h2>Kết nối cùng hội viên Chapter 11</h2></div><a class="d-link" href="members.html">Danh sách hội viên →</a></div><div class="d-home-members">${actives().slice(0,3).map(memberCardV6).join('')||empty('Chưa có hội viên công khai.')}<a class="d-map-card" href="member-map.html"><span class="d-map-art" aria-hidden="true">⌖</span><h3>Bản đồ hội viên</h3><p>Thông tin vị trí theo quyền công khai.</p><span class="d-link">Xem bản đồ →</span></a></div></div></section>
 <section class="d-section" id="activities"><div class="d-wrap"><div class="d-section-head"><h2>Các hoạt động</h2><div class="d-term-tabs"><button type="button" data-media="video" aria-pressed="true">Video</button><button type="button" data-media="album" aria-pressed="false">Album ảnh</button></div></div><div id="d-media-grid" class="d-media-grid">${designMediaTeaser()}</div></div></section>
 <section class="d-section d-tint"><div class="d-wrap d-process-teaser"><h2>20 bước<br>buổi họp</h2>${[0,3,13,19].map(i=>`<a href="meeting-process.html#step-${i+1}"><span>${String(i+1).padStart(2,'0')}</span><p>${designSteps[i]}</p></a>`).join('')}<a class="d-link" href="meeting-process.html">Xem đủ 20 bước →</a></div></section>
`);
 qa('[data-term]').forEach(b=>b.addEventListener('click',()=>{qa('[data-term]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));q('#d-term-card').innerHTML=designTermCard(Number(b.dataset.term))}));
 qa('[data-media]').forEach(b=>b.addEventListener('click',()=>{qa('[data-media]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));q('#d-media-grid').innerHTML=designMediaTeaser(b.dataset.media)}));
 const layout=heroLayout(S.config.site.heroLayout);function fit(){const f=q('.d-hero-photo'),im=f?.querySelector('img');if(!f||!im)return;const l=layout[innerWidth<=700?'mobile':'desktop'];f.style.setProperty('--photo-x',l.x+'%');f.style.setProperty('--photo-y',l.y+'%');im.style.transform=`scale(${l.zoom/100})`;im.style.transformOrigin=`${l.x}% ${l.y}%`}fit();
 window.addEventListener('resize',fit,{signal:designEvents.signal});
};
renderMembersV6=function(){designMount(`<section class="d-title"><div class="d-wrap"><span class="d-eyebrow">CỘNG ĐỒNG CHAPTER 11</span><h1>Những kết nối tạo nên giá trị</h1><p>Tìm hội viên theo doanh nghiệp, ngành nghề và Power Team.</p></div></section><section class="d-section"><div class="d-wrap"><div class="d-filters"><label>Tìm hội viên<input id="d-search" type="search" placeholder="Tên, doanh nghiệp hoặc ngành nghề"></label><label>Power Team<select id="d-power">${opts([['','Tất cả Power Team'],...S.powerTeams.map(p=>[p.id,p.name])])}</select></label><label>Ngành nghề<select id="d-industry">${opts([['','Tất cả ngành nghề'],...[...new Set(actives().flatMap(m=>[m.industry,m.secondaryIndustry]).filter(Boolean))]])}</select></label></div><p id="d-count" role="status"></p><div id="d-members" class="d-member-grid"></div></div></section>`);const filter=()=>{const word=val('d-search').toLocaleLowerCase('vi'),power=val('d-power'),industry=val('d-industry');const list=actives().filter(m=>(!power||m.powerTeamId===power)&&(!industry||[m.industry,m.secondaryIndustry].includes(industry))&&[m.fullName,m.company,m.industry,m.secondaryIndustry].join(' ').toLocaleLowerCase('vi').includes(word));q('#d-count').textContent=list.length+' hội viên';q('#d-members').innerHTML=list.map(memberCardV6).join('')||empty('Không tìm thấy hội viên. Hãy thử từ khóa hoặc bộ lọc khác.')};['d-search','d-power','d-industry'].forEach(id=>q('#'+id).addEventListener(id==='d-search'?'input':'change',filter));filter()};
function designDetails(items){return `<dl class="d-details">${items.map(([label,value])=>`<div><dt>${label}</dt><dd>${esc(value||'Đang cập nhật')}</dd></div>`).join('')}</dl>`}
function renderPublicProfile(){const id=new URLSearchParams(location.search).get('id'),m=actives().find(m=>m.id===id);if(!m){designMount(`<section class="d-section d-wrap"><h1>Không tìm thấy hồ sơ công khai</h1><p>Hồ sơ không tồn tại hoặc không còn hoạt động.</p><a class="d-button" href="members.html">Về danh sách hội viên</a></section>`);return}designMount(`<section class="d-profile-cover"><div class="d-wrap"><a href="members.html">← Danh sách hội viên</a><span>HỒ SƠ CÔNG KHAI</span></div></section><section class="d-wrap d-profile-heading">${designPhoto(m)}<div><span class="d-eyebrow">HỘI VIÊN CHAPTER 11</span><h1>${esc(m.fullName)}</h1><p>${esc(m.title||'')} ${m.title?'·':''} ${esc(m.company)}</p><span class="d-tag">${esc(m.industry||'Đang cập nhật ngành nghề')}</span><span class="d-tag">${esc(powerName(m.powerTeamId))}</span></div><a class="d-button" href="${meetingHref('guest-register.html')}">Gặp gỡ tại buổi họp →</a></section><div class="d-wrap d-profile-layout"><div><section class="d-panel"><span class="d-eyebrow">DOANH NGHIỆP</span><h2>${esc(m.company||'Thông tin doanh nghiệp')}</h2><p class="d-prose">${esc(m.products||'Sản phẩm và dịch vụ đang được cập nhật.')}</p>${designDetails([['Ngành nghề chính',m.industry],['Ngành nghề phụ',m.secondaryIndustry],['Địa chỉ doanh nghiệp',m.businessAddress]])}</section><section class="d-panel"><h2>Kết nối cùng ${esc(m.fullName.split(' ').at(-1))}</h2><p>Tham gia buổi họp Chapter 11 để trao đổi nhu cầu và tìm hiểu cơ hội hợp tác.</p><a class="d-link" href="${meetingHref('meeting.html')}">Thông tin buổi họp gần nhất →</a></section></div><aside><section class="d-panel"><span class="d-eyebrow">THÔNG TIN KẾT NỐI</span><h3>Hội viên Chapter 11</h3>${designDetails([['Điện thoại',publicPhone(m.phone)],['Doanh nghiệp',m.company],['Power Team',powerName(m.powerTeamId)]])}<p class="d-small">Số điện thoại được che 3 số giữa trên trang công khai.</p></section>${currentMember()?.id===m.id?'<a class="d-button d-full" href="member-portal.html">Vào không gian riêng của tôi →</a>':''}</aside></div>`)}
function renderDesignAbout(){designMount(`<section class="d-title"><div class="d-wrap"><span class="d-eyebrow">TỔNG QUAN VỀ VBNA</span><h1>Nối kết Doanh nhân<br>Nâng tầm Doanh nghiệp</h1><p>Phát triển từ những mối quan hệ lâu dài và bền vững.</p></div></section><div class="d-wrap d-article-layout"><aside class="d-article-nav">${designOverview.map(([id,title])=>`<a href="#${id}">${title}</a>`).join('')}</aside><div>${designOverview.map(([id,title,content],i)=>`<section class="d-panel" id="${id}"><span class="d-eyebrow">0${i+1} / VBNA</span><h2>${title}</h2>${Array.isArray(content)?'<ol>'+content.map(t=>'<li>'+esc(t)+'</li>').join('')+'</ol>':`<p class="d-prose">${esc(content)}</p>`}</section>`).join('')}<a class="d-button" href="guest-register.html">Đăng ký trở thành khách mời →</a></div></div>`)}
function renderDesignLeadership(){let n=Number(new URLSearchParams(location.search).get('term')||7);if(![1,2,3,4,5,6,7].includes(n))n=7;const history=S.config.leadershipTerms?.find(t=>t.number===n);designMount(`<section class="d-title"><div class="d-wrap"><span class="d-eyebrow">CON NGƯỜI CHAPTER 11</span><h1>BĐH các nhiệm kỳ</h1><p>Tiếp nối những giá trị. Đồng hành cùng doanh nghiệp hội viên.</p></div></section><section class="d-section d-wrap">${designTermTabs(n)}<div class="d-panel"><span class="d-eyebrow">${n<=2?7:n<=6?8:9} BAN</span><h2>Ban điều hành nhiệm kỳ ${n}</h2>${history?.members?.length?`<div class="d-member-grid">${history.members.map(x=>{const m=S.members.find(m=>m.id===x.memberId);return m?`<div><p>${esc(x.role)}</p>${memberCardV6(m)}</div>`:''}).join('')}</div>`:'<p>Danh sách nhân sự và quan hệ giữa các ban của nhiệm kỳ này đang được cập nhật.</p><p class="d-small">Sơ đồ lộ trình sẽ hiển thị từ dưới lên trên khi có đủ thông tin cơ cấu.</p>'}</div><section id="founders" class="d-panel"><span class="d-eyebrow">NHỮNG NGƯỜI ĐẶT NỀN MÓNG</span><h2>Giám đốc mở & Trưởng ban định hướng</h2><div class="d-founder-slots"><article><span>01</span><h3>Giám đốc mở</h3><p>Thông tin đang cập nhật</p></article><article><span>02</span><h3>Giám đốc mở</h3><p>Thông tin đang cập nhật</p></article><article><span>↗</span><h3>Trưởng ban định hướng</h3><p>Thông tin đang cập nhật</p></article></div></section></section>`)}
function renderDesignProcess(){designMount(`<section class="d-title"><div class="d-wrap"><span class="d-eyebrow">KẾT NỐI KINH DOANH THƯỜNG TUẦN</span><h1>20 bước buổi họp</h1><p>Một hành trình kết nối, chia sẻ và trao cơ hội.</p><a class="d-button" href="${meetingHref('guest-register.html')}">Đăng ký tham gia →</a></div></section><section class="d-section d-wrap"><ol class="d-steps">${designSteps.map((s,i)=>`<li id="step-${i+1}"><span>${String(i+1).padStart(2,'0')}</span><div><h2>${s}</h2>${i===16?'<p>Nội dung trong chương trình buổi họp, do Ban Sự kiện điều phối.</p>':''}</div></li>`).join('')}</ol></section>`)}
function renderDesignMap(){designMount(`<section class="d-title"><div class="d-wrap"><span class="d-eyebrow">MẠNG LƯỚI CHAPTER 11</span><h1>Bản đồ hội viên</h1><p>Kết nối từ vị trí doanh nghiệp của hội viên.</p></div></section><section class="d-section d-wrap"><div class="d-panel d-map-pending"><span aria-hidden="true">⌖</span><h2>Bản đồ đang được chuẩn bị</h2><p>Chưa có tọa độ và phạm vi cho phép hiển thị địa chỉ nhà. Địa chỉ nhà riêng chưa được đưa lên bản đồ công khai.</p><a class="d-button" href="members.html">Xem danh sách và địa chỉ doanh nghiệp →</a></div></section>`)}
function renderDesignSummary(){const requested=new URLSearchParams(location.search).get('meeting'),m=requested?S.meetings.find(x=>x.id===requested):designMeeting();if(!m){designMount('<section class="d-section d-wrap"><h1>Chưa có thông tin buổi họp</h1><a href="index.html">Về trang chủ</a></section>');return}const a=S.attendance.filter(x=>x.meetingId===m.id),ops=S.opportunities.filter(x=>x.meetingId===m.id);designMount(`<section class="d-title"><div class="d-wrap"><span class="d-eyebrow">BÁO CÁO SƠ BỘ</span><h1>${esc(m.name)}</h1><p>${fmtDate(m.date)} · ${esc(m.location)}</p></div></section><section class="d-section d-wrap"><div class="d-metrics">${[['Lượt tham dự',a.length],['Hội viên tham dự',a.filter(x=>x.personType==='member').length],['Khách mời tham dự',a.filter(x=>x.personType!=='member').length],['Cơ hội đã trao',ops.length]].map(([t,v])=>`<div><span>${t}</span><strong>${v}</strong></div>`).join('')}</div><p class="d-small">Tổng hợp từ dữ liệu chạy thử trên trình duyệt này. Không công khai chi tiết cơ hội hoặc tài chính cá nhân.</p><a class="d-button" href="${meetingHref('meeting.html',m)}">Về trang buổi họp →</a></section>`)}
renderMedia=function(){const kind=location.hash==='#album'?'album':'video';designMount(`<section class="d-title"><div class="d-wrap"><span class="d-eyebrow">NHỊP SỐNG CHAPTER 11</span><h1>Các hoạt động</h1><p>Lưu giữ những kết nối và khoảnh khắc đáng nhớ.</p></div></section><section class="d-section d-wrap"><div class="d-term-tabs"><a href="#video" ${kind==='video'?'aria-current="page"':''}>Video</a><a href="#album" ${kind==='album'?'aria-current="page"':''}>Album ảnh</a></div><div class="d-media-grid">${S.media.filter(m=>m.kind===kind).map(m=>`<article class="d-panel">${kind==='video'&&videoId(m.url)?`<iframe title="${esc(m.title)}" src="https://www.youtube-nocookie.com/embed/${videoId(m.url)}" loading="lazy" allowfullscreen></iframe>`:imageSrc(m.images?.[0])?`<img class="d-album-cover" src="${esc(imageSrc(m.images[0]))}" alt="${esc(m.title)}">`:''}<h2>${esc(m.title)}</h2><p>${esc(m.description)}</p>${kind==='album'?`<button class="d-button" data-album="${esc(m.id)}">Xem album (${m.images?.length||0} ảnh${m.driveLinks?.length?' · '+m.driveLinks.length+' link Drive':''})</button>`:''}</article>`).join('')||designMediaTeaser(kind)}</div></section>`);qa('[data-album]').forEach(b=>b.addEventListener('click',()=>showAlbum(b.dataset.album)))};
function portalMetrics(m){const given=S.opportunities.filter(o=>o.giverId===m.id),received=S.opportunities.filter(o=>o.receiverType==='member'&&o.receiverId===m.id),att=S.attendance.filter(a=>a.personType==='member'&&a.personId===m.id),fees=S.obligations.filter(o=>o.memberId===m.id&&o.status!=='pending');return {given,received,att,fees}}
function privateContent(m,tab){const {given,received,att,fees}=portalMetrics(m);const notes=S.notifications.filter(n=>n.memberId===m.id);const metrics=`<div class="d-metrics">${[['Cơ hội đã trao',given.length],['Cơ hội đã nhận',received.length],['Buổi đã tham dự',att.length],['Phí đã lập còn nợ',money(fees.reduce((v,o)=>v+debtFor(o),0))]].map(([t,v])=>`<div><span>${t}</span><strong>${v}</strong></div>`).join('')}</div>`;
 if(tab==='overview')return `${metrics}<div class="d-private-grid"><section class="d-panel"><span class="d-eyebrow">HOẠT ĐỘNG CỦA TÔI</span><h2>Cùng kết nối mỗi tuần</h2><p>Trao cơ hội, gặp gỡ hội viên và theo dõi kết quả hợp tác.</p><div class="d-action-row"><a class="d-button" href="${meetingHref('opportunity.html')}">Trao cơ hội →</a><a class="d-button d-secondary" href="${meetingHref('checkin.html')}">Điểm danh</a></div><h3>Thông báo gần đây</h3>${notes.slice(-3).reverse().map(n=>`<p class="d-note">${esc(n.text)}</p>`).join('')||'<p class="d-small">Chưa có thông báo mới dành cho anh/chị.</p>'}</section><section class="d-panel"><span class="d-eyebrow">HỒ SƠ CỦA TÔI</span><h2>${esc(m.company)}</h2>${designDetails([['Ngành nghề chính',m.industry],['Power Team',powerName(m.powerTeamId)],['Ngày gia nhập',m.joinDate?fmtDate(m.joinDate):'Đang cập nhật']])}<a class="d-link" href="#profile">Xem & cập nhật hồ sơ →</a></section></div><section class="d-panel"><div class="d-section-head"><h2>Dashboard các Ban</h2><a class="d-link" href="departments.html">Xem tất cả →</a></div><div class="d-departments">${S.departments.map(d=>`<a href="departments.html?dep=${encodeURIComponent(d.id)}"><span>${esc(d.name)}</span><b>↗</b></a>`).join('')}</div></section>`;
 if(tab==='profile')return `<section class="d-panel"><div class="d-section-head"><div><span class="d-eyebrow">THÔNG TIN RIÊNG TƯ</span><h2>Hồ sơ của tôi</h2></div><button class="d-button" onclick="editOwnProfile()">Đề nghị cập nhật</button></div>${designDetails([['Họ tên',m.fullName],['Số điện thoại',m.phone],['Email',m.email],['Địa chỉ nhà riêng',m.homeAddress],['Ngày sinh',m.dob?fmtDate(m.dob):''],['Ngày gia nhập',m.joinDate?fmtDate(m.joinDate):''],['Doanh nghiệp',m.company],['Địa chỉ doanh nghiệp',m.businessAddress],['Ngành nghề chính',m.industry],['Ngành nghề phụ',m.secondaryIndustry],['Sản phẩm / Dịch vụ',m.products]])}<p class="d-small">Thay đổi thông tin được gửi Chủ tịch / Admin phê duyệt.</p>${S.approvals.filter(a=>a.type==='profile'&&a.entityId===m.id&&a.status==='pending').length?'<p class="d-note">Anh/chị có đề nghị cập nhật đang chờ duyệt.</p>':''}<a class="d-link" href="${designURL('member-profile.html',m.id)}">Xem hồ sơ công khai của tôi →</a></section>`;
 if(tab==='opportunities')return `<section class="d-panel"><div class="d-section-head"><h2>Cơ hội tôi nhận</h2><a class="d-button" href="${meetingHref('opportunity.html')}">Trao cơ hội mới →</a></div>${table(['Người trao','Liên hệ','Loại','SĐT người dùng dịch vụ','Ngày dự kiến Dance','Giá trị dự kiến','Đã xác nhận','Kết quả'],received.map(o=>[esc((o.giverName||memberName(o.giverId))),esc(o.giverPhone||S.members.find(x=>x.id===o.giverId)?.phone),esc(o.type),esc(o.serviceUserPhone||'—'),o.danceDate?fmtDate(o.danceDate):'—',money(o.value),o.confirmedAt?money(o.confirmedValue):'Chưa xác nhận',o.confirmedAt?statusChip(o.status):`<button class="d-button" data-confirm-opportunity="${esc(o.id)}">Xác nhận</button>`]))}</section><section class="d-panel"><h2>Cơ hội tôi trao</h2>${table(['Người nhận','Ngày trao','Dự kiến','Thực nhận','Kết quả'],given.map(o=>[esc(o.receiverName),fmtDate(o.createdAt),money(o.value),o.confirmedAt?money(o.confirmedValue):'Chưa xác nhận',statusChip(o.status)]))}</section>`;
 if(tab==='finance')return `<section class="d-panel"><span class="d-eyebrow">TÀI CHÍNH CÁ NHÂN</span><h2>Các khoản phí của tôi</h2>${table(['Khoản phí','Hạn nộp','Phải thu','Đã thu','Còn nợ'],fees.map(o=>[esc(o.label),fmtDate(o.due),money(o.amount),money(paidFor(o.id)),money(debtFor(o))]))}<p class="d-small">Hạn thường niên: ${m.annualDueDate?fmtDate(m.annualDueDate):'Đang cập nhật'}. Ban Thư ký xác nhận các khoản đã nộp.</p></section><section class="d-panel"><h2>Lịch sử thanh toán</h2>${table(['Khoản phí','Kỳ','Số tiền','Trạng thái'],S.feePayments.filter(f=>f.memberId===m.id).map(f=>[f.feeType==='annual'?'Thường niên':'Phí quỹ',esc(f.period),money(f.amount),f.status==='confirmed'?'Đã xác nhận':'Chờ xác nhận']))}</section>`;
 if(tab==='attendance')return `<section class="d-panel"><div class="d-section-head"><h2>Lịch sử điểm danh</h2><a class="d-button" href="${meetingHref('checkin.html')}">Điểm danh buổi họp →</a></div>${table(['Buổi họp','Ngày','Thời gian điểm danh'],att.slice().reverse().map(a=>{const meeting=S.meetings.find(x=>x.id===a.meetingId);return [esc(meeting?.name||'Buổi họp'),meeting?fmtDate(meeting.date):'—',fmtDT(a.checkedAt)]}))}</section>`;
 return `<section class="d-panel"><span class="d-eyebrow">DÀNH CHO ANH/CHỊ</span><h2>Thông báo</h2>${notes.slice().reverse().map(n=>`<article class="d-note"><small>${n.createdAt?fmtDT(n.createdAt):''}</small><p>${esc(n.text)}</p></article>`).join('')||empty('Chưa có thông báo dành cho anh/chị.')}</section>`;
}
renderPortalV6=function(){if(!requireAuth())return;const m=currentMember();if(!m||m.status!=='active'){designMount('<section class="d-section d-wrap"><h1>Chưa có hồ sơ hội viên hoạt động</h1><p>Tài khoản này chưa liên kết với hồ sơ hội viên đang hoạt động.</p><a class="d-button" href="support.html">Liên hệ hỗ trợ</a></section>');return}let tab=location.hash.slice(1);if(!designTabs.some(([id])=>id===tab))tab='overview';designMount(`<section class="d-portal-top"><div class="d-wrap"><div><span class="d-eyebrow">KHÔNG GIAN RIÊNG TƯ</span><h1>Xin chào, ${esc(m.fullName)}</h1><p>${esc(m.company)} · ${esc(powerName(m.powerTeamId))}</p></div>${designPhoto(m)}</div></section><div class="d-wrap d-portal-layout"><aside class="d-portal-sidebar"><nav aria-label="Không gian hội viên">${designTabs.map(([id,name],i)=>`<a href="#${id}" ${id===tab?'aria-current="page"':''}><span>0${i+1}</span>${name}</a>`).join('')}</nav><a class="d-link" href="support.html">Hỗ trợ hội viên ↗</a><button class="d-logout" onclick="logout()">Đăng xuất</button></aside><div class="d-portal-content" id="memberPortal">${privateContent(m,tab)}</div></div>`, 'design-private');qa('[data-confirm-opportunity]').forEach(b=>b.addEventListener('click',()=>confirmOpportunityForm(b.dataset.confirmOpportunity)))};
const portalBeforeMobileBar=renderPortalV6;
renderPortalV6=function(){portalBeforeMobileBar();if(!document.body.classList.contains('design-private'))return;const active=location.hash.slice(1)||'overview';document.body.insertAdjacentHTML('beforeend',`<nav class="d-app-bar" aria-label="Thanh công cụ hội viên">${[['overview','⌂','Trang chủ'],['opportunities','⇄','Cơ hội'],['finance','▤','Tài chính'],['attendance','✓','Điểm danh'],['profile','○','Cá nhân']].map(([id,icon,label])=>`<a href="#${id}" ${active===id?'aria-current="page"':''}><span aria-hidden="true">${icon}</span>${label}</a>`).join('')}</nav>`);q('.d-portal-sidebar').insertAdjacentHTML('beforeend','<a class="d-mobile-notices d-link" href="#notifications">Thông báo</a>');q('.d-portal-sidebar nav a[aria-current="page"]')?.scrollIntoView({block:'nearest',inline:'nearest'});};
const designBootBefore=bootV6;
bootV6=function(){const page=document.body.dataset.page;const extra={'about-public':renderDesignAbout,'leadership-public':renderDesignLeadership,'meeting-process':renderDesignProcess,'member-profile':renderPublicProfile,'member-map':renderDesignMap,'meeting-summary':renderDesignSummary};if(extra[page])extra[page]();else designBootBefore();if(location.hash&&['about-public','leadership-public','meeting-process'].includes(page))document.getElementById(location.hash.slice(1))?.scrollIntoView()};
window.addEventListener('hashchange',()=>{const p=document.body.dataset.page;if(p==='member-portal'&&currentUser()&&!currentUser().forcePasswordChange)renderPortalV6();if(p==='media')renderMedia()});

