function overviewPhoto(){return `<figure class="ov-photo"><img src="${esc(heroSource(S.config.site.heroImage))}" alt="Hình ảnh minh họa không gian kết nối doanh nhân" loading="lazy"><figcaption>Hình ảnh minh họa</figcaption></figure>`}
