/* One shared footer for public pages and a quieter version for work screens. */
function syncV7Footer(){
 const page=document.body.dataset.page;
 const compact=['admin','departments','finance','finance-entry','reports','settings','member-management','support','lucky','member-portal'].includes(page);
 let footer=document.querySelector('body > .f7-footer');
 // Some older pages still ship a static footer in their HTML shell.
 document.querySelectorAll('body > footer, body > .public-footer, body > .footer').forEach(el=>{if(el!==footer)el.remove()});
 if(!footer){document.body.insertAdjacentHTML('beforeend',publicFooter());footer=document.querySelector('body > .f7-footer')}
 footer.classList.toggle('f7-compact',compact);
}
const bootBeforeFooterSync=bootV6;
bootV6=function(){
 bootBeforeFooterSync();syncV7Footer();
 // Report/portal/settings renderers may replace the body after an action.
 const observer=new MutationObserver(()=>{if(!document.querySelector('body > .f7-footer')){observer.disconnect();syncV7Footer();observer.observe(document.body,{childList:true})}});
 observer.observe(document.body,{childList:true});
};

