const V7_VIEW_FEATURES=[['dashboard','Tổng quan nội bộ'],['personal','Hồ sơ cá nhân'],['members','Hội viên'],['guests','Khách mời / CRM'],['meetings','Buổi họp'],['attendance','Điểm danh'],['opportunities','Cơ hội'],['finance','Tài chính / Công nợ'],['training','Đào tạo'],['events','Sự kiện / Truyền thông'],['development','Phát triển'],['orientation','Định hướng'],['support_director','Giám đốc hỗ trợ'],['documents','Tài liệu'],['reports','Báo cáo'],['approvals','Phê duyệt'],['settings','Cài đặt'],['lucky','Lucky Draw'],['support','Hỗ trợ']];
