const originalRoleLabelV7=roleLabel;roleLabel=r=>v7RoleRows().find(x=>x.id===r)?.title||originalRoleLabelV7(r);
function defaultRoleViews(role){const common=['personal','support','dashboard','members','guests','meetings','attendance','training','events','development','orientation','support_director'];if(role==='president')return V7_VIEW_FEATURES.map(x=>x[0]);const group=V7_ROLE_GROUPS.find(g=>g.roles.some(r=>r[0]===role))?.id;const extra={vice:['dashboard','members','meetings','attendance','reports'],secretariat:['finance','documents','reports'],training:['training'],guests:['guests','meetings'],events:['events','documents','lucky'],development:['development'],orientation:['orientation'],support_director:['support_director'],member:[]};return [...common,...(extra[group]||[])]}
function roleViewEnabled(role,key){if(['personal','dashboard','members','guests','meetings','attendance','training','events','development','orientation','support_director'].includes(key))return true;const rule=S.config.roleViewPermissions?.[role];return S.config.roleViewPermissions?(Array.isArray(rule)&&rule.includes(key)):defaultRoleViews(role).includes(key)}
