renderAccountSettings=function(){if(!isAdmin())return;const host=q('.report-page');if(!host)return;q('#v7-role-settings')?.remove();host.insertAdjacentHTML('beforeend',`<section id="v7-role-settings" class="panel"><div class="rm-heading"><div><span class="eyebrow">QUẢN TRỊ HỆ THỐNG</span><h2>Phân quyền theo đối tượng</h2><p>Các ban và hồ sơ cá nhân được xem chung. Chọn thêm hạng mục được xem cho từng chức danh. Gán ban, chức danh và nhiệm vụ tại Quản lý hội viên → Phân công.</p></div><span class="chip red">Chỉ Admin được thay đổi</span></div><p class="notice">Các mục xem chung luôn mở cho hội viên. Với mục hạn chế, tích ô để cấp quyền xem. Quyền sửa, xóa và phê duyệt không được cấp bằng bảng này. Admin luôn có quyền quản trị.</p><form id="roleViewForm" onsubmit="saveRoleViewsV7(event)"><div class="rm-scroll" tabindex="0" role="region" aria-label="Bảng quyền xem, cuộn ngang để xem các hạng mục"><table class="rm-table"><thead><tr><th scope="col">Đối tượng</th><th scope="col">Chức danh chi tiết</th>${V7_VIEW_FEATURES.map(([key,name])=>`<th scope="col"><span>${esc(name)}</span><button type="button" class="rm-column" data-feature="${key}" onclick="toggleRoleColumnV7('${key}')" aria-label="Đảo chọn toàn cột ${esc(name)}">Chọn cột</button></th>`).join('')}</tr></thead><tbody>${v7RoleRows().map(r=>`<tr><th scope="row">${esc(r.groupName)}</th><td>${esc(r.title)}</td>${V7_VIEW_FEATURES.map(([key,name])=>`<td><input type="checkbox" data-view-role="${r.id}" data-view-feature="${key}" aria-label="${esc(r.title)} — Xem ${esc(name)}" ${roleViewEnabled(r.id,key)?'checked':''}></td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="rm-save"><span>Cuộn ngang trong bảng để xem đủ ${V7_VIEW_FEATURES.length} hạng mục.</span><button class="btn btn-wine" type="submit">Lưu bảng quyền xem</button></div><p id="roleViewStatus" role="status"></p></form><p><a class="btn btn-outline" href="member-management.html#memberAssignmentsV7">Mở Phân công hội viên</a></p></section>`)};
