/* Shared executive dashboard for administrators and permitted read-only accounts. */
let dashboardFilterV7=null;
renderDashboard=function(){
 const host=q('#section-dashboard');if(!host)return;
 const today=localDay(),f=dashboardFilterV7||{mode:'term',date:today,month:today.slice(0,7),year:today.slice(0,4),quarter:String(Math.ceil(+today.slice(5,7)/3)),meeting:activeMeeting()?.id||S.meetings[0]?.id||''};dashboardFilterV7=f;
 const d=C11Dashboard.compute(S,f,today,R),labels={new:'Mới đăng ký',unreachable:'Chưa liên hệ được',contacted:'Đã liên hệ',invited:'Đã mời',attended:'Đã tham dự',interested:'Quan tâm hội viên',application:'Đang làm hồ sơ',approved:'Đã kết nạp',declined:'Từ chối tham gia'};
 const card=(label,value,note,id)=>`<div class="kpi"><span>${label}</span><strong ${id?`id="${id}"`:''}>${value}</strong><small>${note}</small></div>`;
 const rank=rows=>rows.length?table(['Họ tên','Số cơ hội','Tổng giá trị cơ hội','Doanh thu xác nhận'],rows.map(x=>[esc(x.name||'Chưa xác định'),x.count,money(x.value),money(x.confirmed)])):'<p class="empty">Chưa có cơ hội trong kỳ đã chọn.</p>';
 host.innerHTML=`<section class="panel db7-filter"><h3>Dữ liệu điều hành</h3><form id="dashboardFilterForm" class="db7-controls"><label>Lọc theo<select id="dbMode">${opts([['term','Lũy kế nhiệm kỳ'],['meeting','Buổi họp'],['week','Tuần'],['month','Tháng'],['quarter','Quý'],['year','Năm']],f.mode)}</select></label><label ${f.mode!=='meeting'?'hidden':''}>Buổi họp<select id="dbMeeting">${opts(S.meetings.filter(m=>m.status!=='cancelled').map(m=>[m.id,`${m.name} · ${m.date}`]),f.meeting)}</select></label><label ${f.mode!=='week'?'hidden':''}>Ngày trong tuần<input id="dbDate" type="date" value="${esc(f.date)}"></label><label ${f.mode!=='month'?'hidden':''}>Tháng<input id="dbMonth" type="month" value="${esc(f.month)}"></label><label ${!['quarter','year'].includes(f.mode)?'hidden':''}>Năm<input id="dbYear" type="number" min="1900" max="2200" value="${esc(f.year)}"></label><label ${f.mode!=='quarter'?'hidden':''}>Quý<select id="dbQuarter">${opts(['1','2','3','4'].map(x=>[x,'Quý '+x]),f.quarter)}</select></label><button class="btn btn-wine" type="submit">Áp dụng</button></form><p id="dbPeriod">${f.mode==='term'?esc(S.config.term.name)+' · ':''}${esc(d.period.start)} — ${esc(d.period.end)} · ${d.meetings} buổi họp đã diễn ra. Dữ liệu đến ${esc(d.period.endData)}.</p>${d.period.start>today?'<p class="notice">Kỳ đã chọn chưa bắt đầu.</p>':''}</section><div class="kpi-grid db7-kpis">${card('Hội viên hoạt động',d.members,'Tại ngày chốt kỳ','kpiMembers')}${card('Tỷ lệ điểm danh',d.attendance===null?'—':d.attendance+'%','Tổng lượt có mặt / tổng lượt cần có mặt','kpiAttendance')}${card('Cơ hội đã trao',d.ops,f.mode==='meeting'?'Cơ hội gắn với buổi họp':'Cơ hội được tạo trong kỳ','kpiOpps')}${card('Doanh thu đã xác nhận',money(d.revenue),f.mode==='meeting'?'Theo kỳ doanh thu buổi họp chính':'Theo ngày xác nhận, giữa hội viên C11','kpiOppValue')}${card('Khách mời trong VBNA',d.internal,'Số người, không cộng lặp qua các buổi','kpiGuestInternal')}${card('Khách mời ngoài VBNA',d.external,'Số người, không cộng lặp qua các buổi','kpiGuestExternal')}${card('Khách mời trong kỳ',d.guests,`${d.unknown} người chưa xác định trong / ngoài VBNA`,'kpiGuests')}${card('Số dư quỹ đến cuối kỳ',money(d.balance),'Thu trừ chi trong kỳ: '+money(d.net),'kpiFund')}</div><div class="dashboard-grid"><section class="panel"><h3>Phễu khách mời</h3><p class="small-text">Khách đăng ký hoặc tham dự trong kỳ; trạng thái CRM hiện tại. Mỗi khách nằm ở một trạng thái.</p><div id="guestFunnel">${Object.entries(labels).map(([k,label])=>`<div class="metric-row"><span>${label}</span><b data-stage="${k}">${d.funnel[k]}</b></div>`).join('')}</div></section><section class="panel"><h3>Cảnh báo cần xử lý</h3><div id="dashboardAlerts">${d.pending?`<div class="notice warn">${d.pending} yêu cầu trong kỳ đang chờ phê duyệt.</div>`:''}${d.missingDocs?`<div class="notice danger">${d.missingDocs} khoản chi trong kỳ chưa có chứng từ.</div>`:''}${!d.pending&&!d.missingDocs?'<p>Không có cảnh báo trong kỳ đã chọn.</p>':''}</div><details><summary>Cách tính dữ liệu</summary><p>Tuần tính từ thứ Hai đến Chủ nhật. Tháng, quý và năm tính theo lịch Việt Nam.</p><p>Khách chưa có phân loại được thống kê riêng, không tự gán là khách ngoài VBNA. Khách điểm danh chưa có hồ sơ CRM không nằm trong phễu.</p><p>Giá trị cơ hội là giá trị dự kiến lúc trao. Doanh thu chỉ tính số tiền đã xác nhận, theo ngày xác nhận; có thể phát sinh từ cơ hội trao ở kỳ trước.</p><p>Với bộ lọc buổi họp, doanh thu theo mốc chốt của hai buổi họp chính liên tiếp.</p><p>Số dư quỹ gồm số dư đầu kỳ đã cấu hình và các giao dịch đã duyệt đến ngày chốt. Power Team: ${S.powerTeams.length} nhóm.</p></details></section></div><div class="dashboard-grid db7-ranks"><section class="panel"><h3>Top người trao cơ hội</h3><div id="topOpportunity">${rank(d.givers)}</div></section><section class="panel"><h3>Top người nhận cơ hội</h3><div id="topRecipients">${rank(d.receivers)}</div></section></div>`;
 const read=()=>({mode:val('dbMode'),date:val('dbDate')||today,month:val('dbMonth')||today.slice(0,7),year:val('dbYear')||today.slice(0,4),quarter:val('dbQuarter'),meeting:val('dbMeeting')});
 q('#dbMode').onchange=()=>{dashboardFilterV7=read();renderDashboard()};q('#dashboardFilterForm').onsubmit=e=>{e.preventDefault();const next=read();if(!next.date||!next.month||!next.year)return toast('Vui lòng chọn kỳ thống kê hợp lệ');dashboardFilterV7=next;renderDashboard()};
};
const submitGuestBeforeDashboardV7=window.submitGuest;
window.submitGuest=e=>{const before=S.guests.length,meeting=new URLSearchParams(location.search).get('meeting');submitGuestBeforeDashboardV7(e);if(S.guests.length>before&&S.meetings.some(m=>m.id===meeting)){S.guests.at(-1).meetingId=meeting;save()}};

