viceGroupV7.name='Ban Phó Chủ tịch / Ban Hội viên';
viceGroupV7.roles.push(['vice_member','Thành viên Ban Phó Chủ tịch / Ban Hội viên']);
function memberAssignmentV7(m){const users=S.users.filter(u=>u.memberId===m.id),role=users.find(u=>u.role!=='admin')?.role||m.chapterAssignment?.role;return {...m.chapterAssignment,role,group:V7_ROLE_GROUPS.find(g=>g.roles.some(([r])=>r===role))?.id}}
function applyMemberAssignmentV7(m,role,duties){const row=v7RoleRows().find(r=>r.id===role);if(!row)return false;const users=S.users.filter(u=>u.memberId===m.id);if(users.some(u=>u.role==='admin'))return false;const before=JSON.stringify(m.chapterAssignment||{});m.chapterAssignment={role,group:row.group,duties,termId:S.config.term.id,updatedAt:iso()};m.departmentIds=row.group==='member'?[]:[row.group];users.forEach(u=>u.role=role);S.config.roleViewPermissions??=Object.fromEntries(v7RoleRows().map(r=>[r.id,defaultRoleViews(r.id)]));m.assignmentHistory??=[];m.assignmentHistory.push({before,after:{...m.chapterAssignment},at:iso(),by:currentUser()?.id});return true}
function memberAssignmentTableV7(){return `<section class="panel" id="memberAssignmentsV7"><h2>Chức danh & nhiệm vụ trong Chapter</h2><p>${esc(S.config.term.name)} · Phân công chức danh đồng thời áp dụng quyền xem đã cấu hình cho chức danh đó.</p>${table(['Họ tên','Ban / Đối tượng','Chức danh chi tiết','Nhiệm vụ','Tài khoản / Quyền xem',''],S.members.filter(m=>isC11(m)&&(!q('#memberStatusFilter')?.value||m.status===val('memberStatusFilter'))&&(!q('#memberSearch')?.value||[m.fullName,m.phone,m.company,m.industry,m.id].join(' ').toLowerCase().includes(val('memberSearch').toLowerCase()))).map(m=>{const a=memberAssignmentV7(m),row=v7RoleRows().find(r=>r.id===a.role),users=S.users.filter(u=>u.memberId===m.id),admin=users.some(u=>u.role==='admin');return [esc(m.fullName),esc(row?.groupName||'Chưa phân công'),esc(row?.title||'—'),esc(a.duties||'Chưa phân công nhiệm vụ'),admin?'Admin — giữ nguyên quyền quản trị':users.length?`${V7_VIEW_FEATURES.filter(([k])=>roleViewEnabled(a.role,k)).length} hạng mục được xem`:'Chưa có tài khoản; áp dụng khi kích hoạt',isAdmin()&&!admin?button('Phân công',`editMemberAssignmentV7('${m.id}')`,'btn-outline btn-sm'):'—']}))}</section>`}
window.editMemberAssignmentV7=id=>{if(!isAdmin())return toast('Chỉ Admin được phân công và gán quyền xem');const m=S.members.find(m=>m.id===id);if(!m||S.users.some(u=>u.memberId===id&&u.role==='admin'))return;const a=memberAssignmentV7(m),group=V7_ROLE_GROUPS.find(g=>g.id===a.group)||V7_ROLE_GROUPS.find(g=>g.id==='member');openModal('Phân công · '+m.fullName,`<form id="memberAssignmentForm" onsubmit="saveMemberAssignmentV7(event,'${esc(id)}')"><p>Nhiệm kỳ: ${esc(S.config.term.name)}</p><div class="form-grid"><div class="field"><label for="maGroup">Ban / Đối tượng</label><select id="maGroup" onchange="changeMemberAssignmentGroupV7()">${opts(V7_ROLE_GROUPS.map(g=>[g.id,g.name]),group.id)}</select></div><div class="field"><label for="maRole">Chức danh chi tiết</label><select id="maRole" onchange="previewMemberAssignmentV7()">${opts(group.roles,a.role||'member')}</select></div></div><div class="field"><label for="maDuties">Nhiệm vụ được giao</label><textarea id="maDuties" rows="4" maxlength="3000" placeholder="Ví dụ: Quản lý phân loại ngành nghề; theo dõi báo cáo KPI…">${esc(a.duties||'')}</textarea></div><div id="maPreview" class="notice"></div><p class="small-text">Đổi chức danh sẽ thay quyền xem của tài khoản theo bảng Cài đặt, không cộng thêm quyền của chức danh cũ. Nhiệm vụ là nội dung phân công, không tự cấp quyền.</p><button class="btn btn-wine" type="submit">Lưu phân công & quyền xem</button></form>`);previewMemberAssignmentV7()};
window.changeMemberAssignmentGroupV7=()=>{q('#maRole').innerHTML=opts(V7_ROLE_GROUPS.find(g=>g.id===val('maGroup'))?.roles||[]);previewMemberAssignmentV7()};
window.previewMemberAssignmentV7=()=>{const list=V7_VIEW_FEATURES.filter(([key])=>roleViewEnabled(val('maRole'),key)).map(([,name])=>esc(name));q('#maPreview').innerHTML='<b>Quyền xem sẽ áp dụng</b><p>'+(list.join(' · ')||'Chưa được tích quyền xem. Admin cần cấu hình chức danh này trong Cài đặt → Phân quyền.')+'</p>'};
window.saveMemberAssignmentV7=(e,id)=>{e.preventDefault();if(!isAdmin())return toast('Chỉ Admin được phân công và gán quyền xem');const m=S.members.find(m=>m.id===id),role=val('maRole'),group=V7_ROLE_GROUPS.find(g=>g.id===val('maGroup'));if(!m||!group?.roles.some(([r])=>r===role))return toast('Vui lòng chọn đúng ban và chức danh');if(!applyMemberAssignmentV7(m,role,val('maDuties').trim()))return toast('Không thay đổi tài khoản Admin tại đây');save();log('Phân công chức danh và nhiệm vụ','Member',m.id+' → '+role);closeModal();if(document.body.dataset.page==='member-management')renderMemberManagement();else renderMembers();toast('Đã lưu phân công và đồng bộ quyền xem','success')};
