 sp.innerHTML=`<div class="toolbar"><h3>Tài trợ & truyền thông</h3><div>${button('Ghi nhận cam kết tài trợ','newSponsorV7()','btn-outline')}${button('Thông báo tài trợ',"postForm('secretariat')",'btn-outline')}</div></div><form id="sponsorFilterV7" class="form-grid">${select('sfStatus','Trạng thái tài trợ',[['','Tất cả'],...Object.entries(statusLabels)],sponsorFilterV7.status)}${field('sfSearch','Tìm nhà tài trợ / nội dung',sponsorFilterV7.search)}<button class="btn btn-outline">Lọc tài trợ</button></form><p class="small-text">Hiển thị cam kết tạo trong kỳ hoặc có tiền nhận trong kỳ, gồm cả phiếu thu tài trợ trực tiếp. “Đã nhận” và “Còn lại” tính đến ngày kết thúc lọc; “Nhận trong kỳ” theo ngày và quỹ đang chọn.</p>${sponsors.length?table(['Nhà tài trợ / Liên hệ','Nội dung / Ngày','Cam kết','Nhận trong kỳ','Đã nhận đến ngày chốt','Còn lại','Trạng thái / Phiếu thu','Thao tác'],sponsors.map(x=>[esc(x.name)+'<br>'+esc(x.contact),esc(x.title)+'<br>'+fmtDate(x.date),x.amount===null?'Không có cam kết':money(x.amount),money(x.period),money(x.paid),x.remaining===null?'—':money(x.remaining),statusLabels[x.status]+'<br>'+x.receipts.map(r=>esc(r.id)+' · '+fmtDate(r.date)+' · '+esc(C11Finance.method(r))).join('<br>'),x.remaining>0?button('Nhận tài trợ',`receivePledgeForm('${x.id}')`,'btn-outline btn-sm'):'—'])):'<p class="empty">Không có tài trợ phù hợp với bộ lọc. Chọn Tất cả thời gian để xem dữ liệu cũ.</p>'}${postsHTML('secretariat')}`;
