window.lockMonthForm=()=>{if(!canLead())return toast('Chỉ Chủ tịch / Admin được khóa sổ');openModal('Khóa sổ tháng',`<form onsubmit="window.lockMonth(event)">${field('lockMonthValue','Tháng cần khóa',financeFilterV7.from?.slice(0,7)||localDay().slice(0,7),'month','required')}<p>Không khóa khi còn phiếu hoặc đề nghị điều chỉnh chờ duyệt. Sau khi khóa, các phiếu trong tháng không thể sửa hoặc bổ sung.</p><div id="lockMonthErrorV7" role="alert"></div><button class="btn btn-wine">Khóa sổ</button></form>`)};
window.lockMonth=e=>{e.preventDefault();const error=message=>{const el=q('#lockMonthErrorV7');if(el){el.className='notice danger';el.textContent=message}else toast(message)};if(!canLead())return error('Chỉ Chủ tịch / Admin được khóa sổ.');const month=val('lockMonthValue'),issues=C11Finance.lockIssues(S,month);if(issues.length)return error(issues.join(' '));const prior=[...S.config.lockedMonths],oldClosings=S.config.monthClosings,oldAudit=S.audit;try{S.config.lockedMonths.push(month);S.config.monthClosings={...oldClosings,[month]:{by:currentUser().id,at:iso(),summary:C11Finance.ledger(S,{from:month+'-01',to:month+'-31'}).summary}};S.audit=[{id:uid('AU'),time:iso(),userId:currentUser().id,action:'Khóa sổ tháng',entity:'Finance',detail:month},...S.audit].slice(0,400);save()}catch(err){S.config.lockedMonths=prior;S.config.monthClosings=oldClosings;S.audit=oldAudit;return error('Không lưu được khóa sổ. Vui lòng kiểm tra dung lượng lưu trữ rồi thử lại.')}closeModal();refreshFinance();toast('Đã khóa sổ tháng '+month,'success')};
window.newSponsorV7=()=>{if(!financeAccess())return;openModal('Ghi nhận cam kết tài trợ',`<form onsubmit="saveSponsorV7(event)">${select('spMember','Hội viên',[['','Nhà tài trợ khác'],...S.members.map(m=>[m.id,m.fullName])])}${field('spName','Tên nhà tài trợ (nếu không chọn hội viên)')}${field('spContact','Điện thoại / Email')}${field('spTitle','Nội dung tài trợ','','text','required')}${field('spAmount','Số tiền cam kết','','number','min="1" required')}${field('spDate','Ngày cam kết',localDay(),'date','required')}<p>Cam kết chưa làm tăng số dư quỹ. Chỉ ghi nhận thu khi xác nhận tiền đã nhận.</p><button class="btn btn-wine">Lưu cam kết</button></form>`)};
window.saveSponsorV7=e=>{e.preventDefault();if(!financeAccess())return toast('Không có quyền ghi nhận tài trợ');const amount=Number(val('spAmount'));if((!val('spMember')&&!val('spName').trim())||!val('spTitle').trim()||!Number.isSafeInteger(amount)||amount<=0)return toast('Nhập nhà tài trợ, nội dung và số tiền nguyên dương');S.pledges.push({id:uid('PL'),memberId:val('spMember')||null,donorName:val('spName').trim(),contact:val('spContact').trim(),title:val('spTitle').trim(),amount,createdAt:val('spDate')+'T12:00:00+07:00',createdBy:currentUser().id});save();closeModal();refreshFinance();toast('Đã lưu cam kết; chưa ghi nhận thu tiền','success')};
window.receivePledgeForm=id=>{if(!financeAccess())return toast('Không có quyền nhận tài trợ');const p=S.pledges.find(p=>p.id===id);if(!p)return toast('Không tìm thấy cam kết tài trợ');const received=sum(S.finance.filter(x=>x.kind==='income'&&x.pledgeId===id&&x.status==='approved'),'amount');openModal('Xác nhận tài trợ đã nhận',`<form onsubmit="receivePledge(event,'${id}')"><p>${esc(p.title||S.posts.find(x=>x.id===p.postId)?.title||id)} · Còn nhận ${money(Math.max(0,p.amount-received))}</p>${field('pledgeReceived','Số tiền nhận thêm',Math.max(0,p.amount-received),'number','min="1" required')}${field('pledgeDate','Ngày thực nhận',localDay(),'date','required')}${select('pledgeMethod','Phương thức',['Chuyển khoản','Tiền mặt'])}${field('pledgeBill','Chứng từ','','file')}<div id="pledgeErrorV7" role="alert"></div><button class="btn btn-wine">Tạo phiếu thu tài trợ</button></form>`)};
window.receivePledge=async(e,id)=>{e.preventDefault();const error=msg=>{const el=q('#pledgeErrorV7');if(el){el.className='notice danger';el.textContent=msg}else toast(msg)};if(!financeAccess())return error('Không có quyền nhận tài trợ');const p=S.pledges.find(x=>x.id===id),amount=Number(val('pledgeReceived')),date=val('pledgeDate'),method=val('pledgeMethod'),remaining=()=>p.amount-sum(S.finance.filter(x=>x.kind==='income'&&x.status==='approved'&&x.pledgeId===id),'amount');if(!p||!date||!Number.isSafeInteger(amount)||amount<=0||amount>remaining())return error('Số tiền phải nguyên dương và không vượt phần cam kết còn lại');if(financeLocked(date))return error('Tháng '+date.slice(0,7)+' đã khóa sổ. Không thể nhận tiền vào tháng này.');const submit=e.target.querySelector('button[type="submit"],button:last-child');if(submit.disabled)return;submit.disabled=true;const oldReceived=p.received,previousLength=S.finance.length,previousAudit=S.audit;let committed=false;try{const files=await persistInputFiles(q('#pledgeBill'),1,'finance');if(financeLocked(date)||amount>remaining())throw Error('Kỳ đã khóa hoặc số tiền còn lại đã thay đổi. Vui lòng kiểm tra lại.');S.finance.push({id:uid('PT'),kind:'income',category:'Tài trợ',pledgeId:id,memberId:p.memberId,donorName:p.donorName,amount,date,method,description:p.title||S.posts.find(x=>x.id===p.postId)?.title||'Tài trợ',files,status:'approved',createdAt:iso(),createdBy:currentUser().id});p.received=p.amount-remaining();S.audit=[{id:uid('AU'),time:iso(),userId:currentUser().id,action:'Nhận tài trợ',entity:'Finance',detail:id+': '+amount+' · '+date},...S.audit].slice(0,400);save();committed=true;closeModal();refreshFinance();toast('Đã ghi nhận thu tài trợ','success')}catch(err){if(!committed){S.finance.splice(previousLength);p.received=oldReceived;S.audit=previousAudit}error(err.message||'Không thể lưu phiếu tài trợ')}finally{submit.disabled=false}};
window.exportLedgerV7=()=>{if(!financeAccess())return;const l=C11Finance.ledger(S,financeFilterV7),rows=[['Phiếu','Ngày','Diễn giải','Quỹ','Thu','Chi','Cộng dồn tiền mặt','Cộng dồn chuyển khoản','Chưa phân loại','Tổng số dư (mọi quỹ)'],['Đầu kỳ','','','','','',l.start['Tiền mặt'],l.start['Chuyển khoản'],l.start['Chưa phân loại'],Object.values(l.start).reduce((a,b)=>a+b,0)],...l.rows.map(x=>[x.id,x.date,x.description,x.fund,x.kind==='income'?x.amount:0,x.kind==='expense'?x.amount:0,x.cash,x.bank,x.unknown,x.balance]),['Cuối kỳ','','','','','',l.closing['Tiền mặt'],l.closing['Chuyển khoản'],l.closing['Chưa phân loại'],Object.values(l.closing).reduce((a,b)=>a+b,0)],[],['Quỹ','Đầu kỳ','Tổng thu','Tổng chi','Cuối kỳ'],...l.summary.map(x=>[x.method,x.opening,x.income,x.expense,x.closing]),['Tổng cộng theo quỹ đã chọn',...['opening','income','expense','closing'].map(k=>l.summary.reduce((n,x)=>n+x[k],0))]];const csv=rows.map(row=>row.map(v=>'"'+String(typeof v==='number'?v:/^[=+@-]/.test(v||'')?"'"+v:v??'').replaceAll('"','""')+'"').join(',')).join('\r\n'),url=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='So_quy_V7.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};

