const activeBeforeResetV7=activeMeeting;activeMeeting=function(){return activeBeforeResetV7()||{id:'',name:'Chưa có buổi họp',date:localDay(),time:'',status:'unconfigured',location:'',type:'main'}};
function renderResetV7(){if(!isAdmin()||q('#resetDataV7'))return;q('.report-page')?.insertAdjacentHTML('beforeend',`<section class="panel" id="resetDataV7"><h2>Reset dữ liệu sau kiểm thử</h2><p>Chỉ Admin được thực hiện. Reset trên trình duyệt và địa chỉ website đang mở; không xóa dữ liệu máy chủ hoặc trên máy khác.</p><div class="notice danger">Toàn bộ: xóa hồ sơ hội viên, tài khoản khác, khách mời, buổi họp, nghiệp vụ, nội dung hoạt động và tệp tải lên không còn dùng. Giữ tài khoản Admin đang đăng nhập, logo, nội dung giới thiệu, tên miền, cấu hình nhiệm kỳ, biểu phí, danh mục ban và bảng quyền xem.</div><p>Theo ban: giữ hội viên, tài khoản, phân công và buổi họp dùng chung; chỉ xóa nghiệp vụ được liệt kê trong bản xem trước. Tài trợ của ban khác vẫn giữ thông báo liên quan.</p>${select('resetScopeV7','Phạm vi reset',Object.entries(C11Reset.scopes),'training')}<button class="btn btn-outline" onclick="previewResetV7()">Xem dữ liệu sẽ xóa</button><div id="resetPreviewV7"></div><p class="small-text">Bản sao lưu ZIP gồm dữ liệu và tệp đính kèm, có thông tin tài khoản: cần cất giữ riêng, không công khai. Reset không khôi phục dữ liệu mẫu.</p>${S.resetFileCleanup?.length?'<button class="btn btn-outline" onclick="retryResetCleanupV7()">Hoàn tất xóa tệp còn lại</button>':''}<p id="resetStatusV7" role="status"></p></section>`);q('#resetScopeV7')?.addEventListener('change',()=>{resetBackupV7=null;q('#resetPreviewV7').innerHTML='';q('#resetStatusV7').textContent='Bấm xem dữ liệu sẽ xóa để kiểm tra phạm vi mới.'})}
const accountSettingsBeforeResetV7=renderAccountSettings;renderAccountSettings=function(){accountSettingsBeforeResetV7();renderResetV7()};
window.previewResetV7=()=>{if(!isAdmin()||resetBusyV7)return;resetBackupV7=null;const scope=val('resetScopeV7'),p=C11Reset.plan(S,scope,currentUser().id,iso());q('#resetPreviewV7').innerHTML=`<h3>${esc(C11Reset.scopes[scope])}</h3>${table(['Nhóm dữ liệu','Số bản ghi sẽ xóa'],p.changes.map(([k,n])=>[esc(({members:'Hội viên',users:'Tài khoản khác',guests:'Khách mời',meetings:'Buổi họp',attendance:'Điểm danh',attendanceNotes:'Ghi chú điểm danh',opportunities:'Cơ hội',finance:'Phiếu thu chi',obligations:'Công nợ',feePayments:'Thanh toán phí',pledges:'Cam kết tài trợ',training:'Đào tạo',media:'Thư viện ảnh/video',events:'Sự kiện',posts:'Thông báo',audit:'Nhật ký cũ',approvals:'Phê duyệt',mailOutbox:'Thư chờ gửi',notifications:'Thông báo nội bộ',supportTickets:'Hỗ trợ',vbnaPeople:'Danh bạ VBNA'})[k]||k),n]))}<p>${['all','secretariat'].includes(scope)?'Số dư quỹ và khóa sổ tháng cũng được xóa.':''} ${['all','vice'].includes(scope)?'Doanh thu đầu kỳ được đặt về 0.':''} ${['all','events','vice'].includes(scope)?'Kết quả Lucky Draw cũng được xóa.':''}</p><button class="btn btn-outline" onclick="backupBeforeResetV7('${scope}')">1. Tải sao lưu ZIP trước reset</button><form onsubmit="executeResetV7(event,'${scope}')"><p><label><input id="resetBackupAckV7" type="checkbox" required> Tôi đã nhận và lưu bản sao lưu ZIP.</label></p><label for="resetConfirmV7">Nhập chính xác: RESET ${esc(scope.toUpperCase())}</label><input id="resetConfirmV7" autocomplete="off" required><button class="btn btn-danger" type="submit">2. Xác nhận reset dữ liệu</button></form>`;q('#resetStatusV7').textContent='Chưa xóa dữ liệu.'};
async function resetFilesV7(){const db=await openFileDB();try{return await new Promise((resolve,reject)=>{const req=db.transaction('files','readonly').objectStore('files').getAll();req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}finally{db.close()}}
window.backupBeforeResetV7=async scope=>{if(!isAdmin()||resetBusyV7)return;resetBusyV7=true;resetBackupV7=null;try{if(localStorage.getItem(KEY)!==resetStorageBaselineV7)throw Error('Dữ liệu đã thay đổi ở cửa sổ khác. Tải lại trang trước khi sao lưu.');save();const raw=localStorage.getItem(KEY);const files=await resetFilesV7(),zip=new JSZip(),manifest=[];zip.file('data.json',raw);for(let i=0;i<files.length;i++){const {blob,...meta}=files[i],path='files/'+i;zip.file(path,await blob.arrayBuffer());manifest.push({...meta,path})}zip.file('files.json',JSON.stringify(manifest));zip.file('README.txt','Sao lưu V7 trước reset. data.json: dữ liệu; files.json: danh mục tệp; files/: nội dung tệp. Chứa dữ liệu riêng tư.');const blob=await zip.generateAsync({type:'blob'});downloadBlob(blob,'VBNA-truoc-reset-'+Date.now()+'.zip');resetBackupV7={scope,raw,keys:files.map(f=>f.key)};q('#resetStatusV7').textContent='Đã tạo bản tải xuống. Kiểm tra ZIP đã được lưu trước khi xác nhận reset.'}catch(e){q('#resetStatusV7').textContent='Không thể sao lưu: '+e.message}finally{resetBusyV7=false}};
async function cleanupResetV7(){const keys=S.resetFileCleanup||[];if(!keys.length)return;const db=await openFileDB();try{await new Promise((resolve,reject)=>{const tx=db.transaction('files','readwrite');keys.forEach(key=>tx.objectStore('files').delete(key));tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||Error('Xóa tệp bị gián đoạn'))});S.resetFileCleanup=[];try{save()}catch(e){S.resetFileCleanup=keys;throw e}}finally{db.close()}}
window.retryResetCleanupV7=async()=>{if(!isAdmin())return;try{await cleanupResetV7();q('#resetStatusV7').textContent='Đã hoàn tất xóa tệp không còn dùng.'}catch(e){q('#resetStatusV7').textContent='Chưa xóa hết tệp: '+e.message}};
window.executeResetV7=async(e,scope)=>{e.preventDefault();if(!isAdmin())return toast('Chỉ Admin được reset');if(resetBusyV7)return;const status=q('#resetStatusV7');if(!resetBackupV7||resetBackupV7.scope!==scope||!q('#resetBackupAckV7')?.checked||val('resetConfirmV7')!=='RESET '+scope.toUpperCase())return status.textContent='Cần tải sao lưu, xác nhận đã lưu và nhập đúng câu xác nhận.';if(resetBackupV7.raw!==localStorage.getItem(KEY)||resetBackupV7.raw!==JSON.stringify(S))return status.textContent='Dữ liệu đã thay đổi sau sao lưu. Hãy tải lại trang và sao lưu lại trước khi reset.';resetBusyV7=true;let committed=false;try{const p=C11Reset.plan(S,scope,currentUser().id,iso()),refs=new Set(p.refs);p.next.resetFileCleanup=resetBackupV7.keys.filter(k=>!refs.has(k)&&(scope==='all'||p.beforeRefs.includes(k)));localStorage.setItem(KEY,JSON.stringify(p.next));S=p.next;resetStorageBaselineV7=localStorage.getItem(KEY);committed=true;if(scope==='all'){localStorage.removeItem('c11_backup_before_v6');for(const key of Object.keys(sessionStorage))if(key.startsWith('feeSeen:')||key.startsWith('postSeen:'))sessionStorage.removeItem(key)}resetBackupV7=null;await cleanupResetV7();status.textContent='Đã reset '+C11Reset.scopes[scope]+'. Tài khoản Admin và cấu hình được giữ lại.';q('#resetPreviewV7').innerHTML='';}catch(err){status.textContent=committed?'Nghiệp vụ đã reset nhưng còn tệp chưa xóa. Bấm “Hoàn tất xóa tệp còn lại” hoặc tải lại Cấu hình. Lỗi: '+err.message:'Chưa reset được dữ liệu: '+err.message;if(committed)q('#resetPreviewV7').innerHTML='<button class="btn btn-outline" onclick="retryResetCleanupV7()">Hoàn tất xóa tệp còn lại</button>'}finally{resetBusyV7=false;if(committed){const message=status.textContent;renderSiteSettings();renderAccountSettings();syncV7Footer();q('#resetStatusV7').textContent=message;q('#resetDataV7').scrollIntoView({block:'start'})}}};

/* Persistent login by default; opting out keeps the session in this tab only. */
session=function(){try{return JSON.parse(sessionStorage.getItem(SESSION)||localStorage.getItem(SESSION)||'null')}catch{return null}};
const loginBeforeLuxuryV7=window.login;window.login=e=>{const remember=q('#rememberLoginV7')?.checked!==false,valid=S.users.find(u=>u.active&&(u.username===val('loginUser')||u.phone===val('loginUser'))&&u.password===val('loginPass'));sessionStorage.removeItem(SESSION);loginBeforeLuxuryV7(e);if(valid&&currentUser()?.id===valid.id&&!remember){sessionStorage.setItem(SESSION,localStorage.getItem(SESSION));localStorage.removeItem(SESSION)}};
const logoutBeforeLuxuryV7=window.logout;window.logout=()=>{sessionStorage.removeItem(SESSION);logoutBeforeLuxuryV7()};
function opportunityMeetingV7(){const id=new URLSearchParams(location.search).get('meeting');return id?S.meetings.find(m=>m.id===id):S.meetings.find(m=>m.status==='open')}
renderOpportunity=function(){const m=opportunityMeetingV7(),member=currentMember();qa('[data-meeting-name]').forEach(el=>el.textContent=m?.name||'Trao cơ hội Chapter 11');const host=q('main');if(!host)return;host.innerHTML=`<form class="form-card" id="publicOpportunityV7" onsubmit="submitOpportunity(event)"><h2>Trao cơ hội cho hội viên Chapter 11</h2><p>${esc(m?.name||'Chưa có buổi họp phù hợp')}</p><div id="opportunityMessageV7" role="status"></div>${member?.status==='active'?`<div class="notice">Người trao: ${esc(member.fullName)}</div>`:`<section id="externalGiver"><h3>Thông tin người trao</h3><div class="form-grid">${field('outsideName','Họ và tên','','text','required autocomplete="name"')}${field('outsidePhone','Số điện thoại','','tel','required autocomplete="tel"')}${select('outsideCategory','Đối tượng',[['guest_external','Khách mời ngoài VBNA'],['guest_vbna','Khách mời trong VBNA']])}<div id="outsideRoleWrap" hidden>${select('outsideRole','Vai trò trong VBNA',[['','Chọn vai trò'],['founder','HĐSL'],['advisor','HĐTV'],['president','Chủ tịch'],['lead','Trưởng ban'],['member','Hội viên']])}</div></div></section>`}<h3>Nội dung trao cơ hội</h3><div id="opportunityRowsV7"></div><button type="button" class="btn btn-outline" onclick="addOpportunityRow()">+ Thêm người nhận</button><button class="btn btn-wine" type="submit" ${m?.status!=='open'?'disabled':''}>Gửi phiếu trao cơ hội</button>${m?.status!=='open'?'<p class="notice">Buổi họp chưa mở hoặc đã đóng nhận cơ hội.</p>':''}</form>`;q('#outsideCategory')?.addEventListener('change',()=>{const inside=val('outsideCategory')==='guest_vbna';q('#outsideRoleWrap').hidden=!inside;q('#outsideRole').required=inside});addOpportunityRow()};
window.addOpportunityRow=()=>{const host=q('#opportunityRowsV7');if(!host)return;const el=document.createElement('section');el.className='lux-opp-row';el.innerHTML=`<div class="form-grid"><div class="field"><label>Hội viên Chapter 11 nhận cơ hội<select class="oppReceiverV7" required>${opts([['','Chọn hội viên'],...actives().map(m=>[m.id,m.fullName+' · '+m.company])])}</select></label></div><div class="field"><label>Loại cơ hội<select class="oppTypeV7">${opts(['Referral cấp 1','Referral cấp 2','Referral cấp 3','Referral cấp 4','Referral cấp 5','Dance'].map(x=>[x,x]))}</select></label></div><div class="field oppValueWrap"><label>Giá trị dự kiến (VNĐ)<input class="oppValueV7" type="number" min="0" step="1" value="0" required></label></div><div class="field oppClientWrap" hidden><label>Số điện thoại người sử dụng dịch vụ (có thể bổ sung sau)<input class="oppClientV7" type="tel"></label></div><div class="field oppDanceWrap" hidden><label>Ngày dự kiến gặp Dance<input class="oppDanceV7" type="date"></label></div><div class="field"><label>Nội dung giới thiệu / ghi chú<textarea class="oppNoteV7" rows="2" maxlength="2000"></textarea></label></div></div><button class="btn btn-outline btn-sm" type="button" onclick="this.closest('.lux-opp-row').remove()">Bỏ dòng</button>`;host.append(el);el.querySelector('.oppTypeV7').onchange=()=>{const dance=el.querySelector('.oppTypeV7').value==='Dance',level2=!dance&&el.querySelector('.oppTypeV7').value!=='Referral cấp 1';el.querySelector('.oppClientWrap').hidden=!level2;el.querySelector('.oppDanceWrap').hidden=!dance;el.querySelector('.oppDanceV7').required=dance;el.querySelector('.oppValueWrap').hidden=dance;el.querySelector('.oppValueV7').required=!dance}};
window.submitOpportunity=e=>{e.preventDefault();const message=q('#opportunityMessageV7'),fail=text=>{message.className='notice danger';message.textContent=text},m=opportunityMeetingV7(),member=currentMember();if(!m||m.status!=='open')return fail('Buổi họp chưa mở hoặc đã đóng nhận cơ hội.');const external=member?.status!=='active',phone=external?val('outsidePhone').replace(/[\s().-]/g,''):member.phone,name=external?val('outsideName').trim():member.fullName,category=external?val('outsideCategory'):'chapter11',role=external?val('outsideRole'):null,validPhone=p=>/^\+?\d{9,15}$/.test(p);if(!name||!validPhone(phone))return fail('Vui lòng nhập họ tên và số điện thoại hợp lệ.');if(category==='guest_vbna'&&!role)return fail('Vui lòng chọn vai trò trong VBNA.');const rows=qa('.lux-opp-row');if(!rows.length)return fail('Cần ít nhất một dòng cơ hội.');const records=[];for(const row of rows){const receiver=S.members.find(x=>x.id===row.querySelector('.oppReceiverV7').value&&x.status==='active'),type=row.querySelector('.oppTypeV7').value,dance=type==='Dance',value=dance?0:Number(row.querySelector('.oppValueV7').value),clientPhone=row.querySelector('.oppClientV7').value.trim(),date=row.querySelector('.oppDanceV7').value;if(!receiver||!Number.isSafeInteger(value)||value<0)return fail('Chọn hội viên nhận và nhập giá trị dự kiến hợp lệ.');if(!dance&&type!=='Referral cấp 1'&&clientPhone&&!validPhone(clientPhone.replace(/[\s().-]/g,'')))return fail('Số điện thoại người sử dụng dịch vụ chưa hợp lệ.');if(dance&&(!date||date<localDay()))return fail('Chọn ngày dự kiến gặp Dance từ hôm nay trở đi.');records.push({id:uid('OP'),meetingId:m.id,giverId:external?null:member.id,giverType:external?'guest':'member',giverName:name,giverPhone:phone,giverCategory:category,giverRole:category==='guest_vbna'?role:null,receiverType:'member',receiverId:receiver.id,receiverName:receiver.fullName,type,value,serviceUserPhone:!dance&&type!=='Referral cấp 1'?clientPhone:'',danceDate:dance?date:'',note:row.querySelector('.oppNoteV7').value.trim(),status:'open',createdAt:iso()})}S.opportunities.push(...records);records.forEach(o=>S.notifications.push({id:uid('N'),memberId:o.receiverId,opportunityId:o.id,text:`${name} (${phone}) vừa trao ${o.type}${o.danceDate?' — dự kiến gặp '+fmtDate(o.danceDate):''}.`,createdAt:iso()}));try{save();message.className='notice success';message.textContent='Đã ghi nhận '+records.length+' cơ hội.';q('#opportunityRowsV7').innerHTML='';addOpportunityRow()}catch(err){S.opportunities=S.opportunities.filter(o=>!records.includes(o));S.notifications=S.notifications.filter(n=>!records.some(o=>o.id===n.opportunityId));fail('Chưa lưu được phiếu: '+err.message)}};
const memberDetailBeforeLuxuryV7=window.viewMember;
window.viewMember=id=>{memberDetailBeforeLuxuryV7(id);if(!isAdmin())return;const u=S.users.find(u=>u.memberId===id&&u.role!=='admin');if(u)q('#modalBody')?.insertAdjacentHTML('beforeend',`<section class="notice"><h3>Hỗ trợ tài khoản — Admin</h3><p>Tài khoản: ${esc(u.username)}</p><button class="btn btn-outline" onclick="revealMemberPasswordV7('${u.id}')">Hiện mật khẩu đang lưu</button><p id="adminPasswordV7" hidden></p></section>`)};
window.revealMemberPasswordV7=id=>{if(!isAdmin())return;const u=S.users.find(u=>u.id===id&&u.role!=='admin');if(!u||!q('#adminPasswordV7'))return;const el=q('#adminPasswordV7');el.hidden=false;el.textContent=u.password||'Mật khẩu dạng mã hóa không thể xem lại; dùng chức năng Reset mật khẩu.';log('Admin xem thông tin đăng nhập','User',u.id);setTimeout(()=>{el.textContent='';el.hidden=true},20000)};
const bootBeforeLuxuryV7=bootV6;bootV6=function(){bootBeforeLuxuryV7();if(document.body.dataset.page==='login'&&!q('#rememberLoginV7'))q('.l7-help')?.insertAdjacentHTML('beforebegin','<label class="lux-remember"><input type="checkbox" id="rememberLoginV7" checked> Ghi nhớ đăng nhập đến khi đăng xuất</label>')};
const confirmBeforeDanceV7=window.confirmOpportunityForm;
window.confirmOpportunityForm=id=>{const o=S.opportunities.find(x=>x.id===id);if(o?.type!=='Dance')return confirmBeforeDanceV7(id);if(o.receiverId!==currentMember()?.id||o.confirmedAt)return toast('Không thể xác nhận cơ hội này');openModal('Kết quả gặp Dance',`<form onsubmit="saveOpportunityResult(event,'${id}')"><p>Người trao: ${esc(o.giverName||memberName(o.giverId))} · ${esc(o.giverPhone||'')}</p><p>Ngày dự kiến: ${fmtDate(o.danceDate)}</p>${select('orStatus','Kết quả',[['success','Đã gặp Dance'],['failed','Không thực hiện']])}<input type="hidden" id="orAmount" value="0">${area('orReason','Ghi chú / Lý do không thực hiện')}<button class="btn btn-wine">Xác nhận kết quả</button></form>`)};

function toolsDepartmentV7(){return document.body.dataset.page==='role-workspace'?new URLSearchParams(location.search).get('view'):new URLSearchParams(location.search).get('dep')}
function teamToolsV7(){return `<section class="panel lux-tools" id="teams"><h2>Power Team & ngành nghề đang mở</h2><form onsubmit="saveTeamsV6(event)"><div class="grid-3">${S.powerTeams.map((p,i)=>`<article class="card">${field('teamName'+i,'Tên Power Team',p.name,'text','required')}${area('teamDesc'+i,'Giới thiệu',p.desc)}${area('teamOpen'+i,'Ngành nghề mở — mỗi ngành một dòng',(p.openIndustries||[]).join('\n'))}</article>`).join('')}</div><button class="btn btn-wine">Lưu danh mục</button></form></section>`}
let birthdayFilterV7={mode:'month',month:String(Number(localDay().slice(5,7))),quarter:String(Math.ceil(Number(localDay().slice(5,7))/3))};
function birthdayToolsV7(){const f=birthdayFilterV7,c=S.config.birthdayWishes||{},manage=canDept('events'),rows=S.members.filter(m=>m.status==='active'&&/^\d{4}-\d{2}-\d{2}$/.test(m.dob||'')&&(f.mode==='month'?Number(m.dob.slice(5,7))===+f.month:Math.ceil(Number(m.dob.slice(5,7))/3)===+f.quarter)).sort((a,b)=>a.dob.slice(5).localeCompare(b.dob.slice(5)));return `<section class="panel lux-tools lux-birthday" id="birthdayToolsV7"><h2>Sinh nhật hội viên</h2><form onsubmit="filterBirthdaysV7(event)" class="form-grid">${select('birthdayPeriod','Xem theo',[['month','Tháng'],['quarter','Quý']],f.mode)}${select('birthdayMonth','Tháng',Array.from({length:12},(_,i)=>[String(i+1),'Tháng '+(i+1)]),f.month)}${select('birthdayQuarter','Quý',['1','2','3','4'].map(q=>[q,'Quý '+q]),f.quarter)}<button class="btn btn-outline">Lọc sinh nhật</button></form><p>${rows.length} hội viên có sinh nhật trong kỳ đã chọn.</p>${table(['Hội viên','Ngày sinh nhật','Email','Lời chúc'],rows.map(m=>[esc(m.fullName),esc(m.dob.slice(8,10)+'/'+m.dob.slice(5,7)),esc(m.email||'Chưa có email'),button('Xem lời chúc',`previewBirthdayV7('${m.id}')`,'btn-outline btn-sm')]))}${manage?`<details><summary>Cài đặt sẵn thư & popup sinh nhật</summary><form onsubmit="saveBirthdayConfigV7(event)">${field('birthdaySubject','Tiêu đề thư',c.subject||'Chúc mừng sinh nhật {ten} — VBNA Chapter 11')}${area('birthdayBody','Lời chúc (dùng {ten}, {tuoi})',c.body||'Kính gửi anh/chị {ten},\n\nVBNA Chapter 11 trân trọng chúc mừng sinh nhật anh/chị. Chúc anh/chị tuổi mới nhiều sức khỏe, hạnh phúc và thành công; tiếp tục lan tỏa những giá trị tốt đẹp cùng cộng đồng doanh nhân.\n\nTrân trọng,\nVBNA Chapter 11') }<label class="inline-check"><input type="checkbox" id="birthdayPopup" ${c.popup?'checked':''}> Hiện popup cho hội viên trong ngày sinh nhật khi đăng nhập</label><label class="inline-check"><input type="checkbox" id="birthdayDraft" ${c.autoDraft?'checked':''}> Tự tạo bản nháp thư sinh nhật khi Ban Sự kiện mở web trong ngày</label><p class="small-text">Thư được lưu bản nháp, chưa tự gửi. Gửi tự động khi đóng trình duyệt cần máy chủ và dịch vụ email được kết nối.</p><button class="btn btn-wine">Lưu cấu hình lời chúc</button></form></details><h3>Thư sinh nhật đã soạn</h3>${table(['Người nhận','Tiêu đề','Trạng thái'],S.mailOutbox.filter(x=>x.kind==='birthday').map(x=>[esc(x.to),esc(x.subject),x.status==='sent'?'Đã gửi':'Bản nháp — chưa gửi']))}`:''}</section>`}
function renderDepartmentToolsV7(){const dep=toolsDepartmentV7();if(!['events','development'].includes(dep)||!currentUser())return;if(roleMatrixActive()&&!canViewV7(dep))return;const host=q('#departmentDashboard')||q('.rm-workspace');if(!host)return;q('#teams')?.remove();q('#birthdayToolsV7')?.remove();q('#media')?.remove();if(dep==='development'&&canDept('development'))host.insertAdjacentHTML('beforeend',teamToolsV7());if(dep==='events'){if(canDept('events'))host.insertAdjacentHTML('beforeend',mediaSettingsHTML());if(canDept('events')&&S.config.birthdayWishes?.autoDraft)queueBirthdayDraftsV7();host.insertAdjacentHTML('beforeend',birthdayToolsV7())}}
const settingsBeforeToolsV7=renderSiteSettings;renderSiteSettings=function(){if(['departments','role-workspace'].includes(document.body.dataset.page)&&['events','development'].includes(toolsDepartmentV7())){if(document.body.dataset.page==='departments')renderDepartmentsV6();else renderRoleWorkspaceV7(toolsDepartmentV7());return}settingsBeforeToolsV7();q('#teams')?.remove();q('#media')?.remove()};
const departmentBeforeToolsV7=renderDepartmentsV6;renderDepartmentsV6=function(){departmentBeforeToolsV7();renderDepartmentToolsV7();qa('a[href="settings.html#teams"]').forEach(a=>{a.href='#teams';a.textContent='Quản lý Power Team'})};
const roleBeforeToolsV7=renderRoleWorkspaceV7;renderRoleWorkspaceV7=function(feature){roleBeforeToolsV7(feature);renderDepartmentToolsV7()};
window.filterBirthdaysV7=e=>{e.preventDefault();birthdayFilterV7={mode:val('birthdayPeriod'),month:val('birthdayMonth'),quarter:val('birthdayQuarter')};renderDepartmentToolsV7()};
window.saveBirthdayConfigV7=e=>{e.preventDefault();if(!canDept('events'))return toast('Chỉ Ban Sự kiện và Admin được cấu hình');S.config.birthdayWishes={subject:val('birthdaySubject').trim(),body:val('birthdayBody').trim(),popup:q('#birthdayPopup').checked,autoDraft:q('#birthdayDraft').checked};save();toast('Đã lưu mẫu thư và thiết lập sinh nhật','success')};
function birthdayTextV7(m){const c=S.config.birthdayWishes||{},age=Number(localDay().slice(0,4))-Number(m.dob?.slice(0,4)),fill=s=>s.replaceAll('{ten}',m.fullName).replaceAll('{tuoi}',age>0?String(age):'');return {subject:fill(c.subject||'Chúc mừng sinh nhật {ten} — VBNA Chapter 11'),body:fill(c.body||'Kính gửi anh/chị {ten},\n\nVBNA Chapter 11 trân trọng chúc mừng sinh nhật anh/chị. Chúc anh/chị tuổi mới nhiều sức khỏe, hạnh phúc và thành công, luôn đồng hành cùng những kết nối tốt đẹp.\n\nTrân trọng,\nVBNA Chapter 11')}}
window.previewBirthdayV7=id=>{if(!canViewV7('events')&&!canDept('events'))return;const m=S.members.find(m=>m.id===id);if(!m)return;const text=birthdayTextV7(m);openModal('Chúc mừng sinh nhật · '+m.fullName,`<h3>${esc(text.subject)}</h3><p style="white-space:pre-line">${esc(text.body)}</p>${canDept('events')?button('Lưu bản nháp email',`saveBirthdayDraftV7('${m.id}')`):''}${m.email&&canDept('events')?`<a class="btn btn-outline" href="mailto:${encodeURIComponent(m.email)}?subject=${encodeURIComponent(text.subject)}&body=${encodeURIComponent(text.body)}">Mở email để gửi</a>`:''}<p class="small-text">Popup xem trước. Chưa gửi email.</p>`)};
window.saveBirthdayDraftV7=id=>{if(!canDept('events'))return;const m=S.members.find(m=>m.id===id);if(!m?.email)return toast('Hội viên chưa có email');const key='birthday:'+id+':'+localDay().slice(0,4);if(S.mailOutbox.some(x=>x.dedupeKey===key))return toast('Đã có thư sinh nhật cho hội viên trong năm này');const text=birthdayTextV7(m);S.mailOutbox.push({id:uid('MAIL'),kind:'birthday',department:'events',memberId:id,to:m.email,...text,status:'draft',dedupeKey:key,createdAt:iso()});save();toast('Đã lưu bản nháp, chưa gửi email','success')};
function queueBirthdayDraftsV7(){const today=localDay().slice(5);S.members.filter(m=>m.status==='active'&&m.dob?.slice(5)===today&&m.email&&!S.mailOutbox.some(x=>x.dedupeKey==='birthday:'+m.id+':'+localDay().slice(0,4))).forEach(m=>saveBirthdayDraftV7(m.id))}
const bootBeforeBirthdayV7=bootV6;bootV6=function(){bootBeforeBirthdayV7();const m=currentMember(),key=m?'birthdayPopup:'+m.id+':'+localDay().slice(0,4):'';if(m&&S.config.birthdayWishes?.popup&&m.dob?.slice(5)===localDay().slice(5)&&!sessionStorage.getItem(key)){const text=birthdayTextV7(m);setTimeout(()=>{if(!q('#modal:not(.hide)')){openModal('Chúc mừng sinh nhật',`<h3>${esc(text.subject)}</h3><p style="white-space:pre-line">${esc(text.body)}</p>`);sessionStorage.setItem(key,'1')}},1000)}};

function canGuestIntakeV7(){return !!currentUser()&&['admin','president','guest_lead','guest_member'].includes(currentUser().role)&&canViewV7('guests')}
function refreshGuestIntakeV7(){if(document.body.dataset.page==='role-workspace')renderRoleWorkspaceV7('guests');else renderDepartmentsV6()}
function mountGuestIntakeV7(){if(toolsDepartmentV7()!=='guests'||!canGuestIntakeV7())return;const host=q('#departmentDashboard')||q('.rm-workspace');if(!host)return;q('#guestIntakeV7')?.remove();host.insertAdjacentHTML('afterbegin',`<section class="panel" id="guestIntakeV7"><div class="toolbar"><h2>Đăng ký khách trước buổi họp</h2>${button('Thêm khách mời','guestIntakeFormV7()')}</div><p>Ban Khách mời nhập giúp hội viên. Đăng ký trước không tự ghi nhận điểm danh.</p>${table(['Khách mời','Người giới thiệu','Buổi họp đăng ký','Thao tác'],S.guests.map(g=>[esc(g.fullName)+'<br>'+esc(g.phone),esc(memberName(g.inviterId)),esc([...new Set([g.meetingId,...(g.meetingIds||[])].filter(Boolean))].map(id=>S.meetings.find(m=>m.id===id)?.name||id).join(', ')||'Chưa chọn'),button('Cập nhật',`guestIntakeFormV7('${g.id}')`,'btn-outline btn-sm')]))}</section>`)}
window.guestIntakeFormV7=(id='')=>{if(!canGuestIntakeV7())return toast('Bạn không có quyền nhập khách mời');const g=S.guests.find(g=>g.id===id)||{},meetings=S.meetings.filter(m=>!m.deletedAt&&!['closed','cancelled'].includes(m.status));openModal(id?'Cập nhật khách mời':'Thêm khách mời trước buổi họp',`<form onsubmit="saveGuestIntakeV7(event,'${esc(id)}')"><div class="form-grid">${select('giMeeting','Buổi họp đăng ký *',[['','Chọn buổi họp'],...meetings.map(m=>[m.id,m.name+' · '+m.date])],g.meetingId||'')}${field('giName','Họ và tên *',g.fullName||'','text','required')}${field('giPhone','Số điện thoại *',g.phone||'','tel','required')}${field('giEmail','Email',g.email||'','email')}${field('giAddress','Địa chỉ',g.address||'')}${field('giDob','Ngày sinh',g.dob||'','date')}${select('giType','Loại hình hoạt động *',['Cá nhân','HKD','Doanh nghiệp'],g.businessType||'Cá nhân')}${field('giCompany','Tên doanh nghiệp / HKD',g.company||'')}${field('giIndustry','Ngành nghề chính *',g.industry||'','text','required')}${select('giInviter','Hội viên giới thiệu',[['','Không có'],...actives().map(m=>[m.id,m.fullName])],g.inviterId||'')}${select('giCategory','Phân loại khách',[['guest_external','Khách ngoài VBNA'],['guest_vbna','Khách trong VBNA']],g.guestCategory||'guest_external')}${field('giChapter','Chapter (nếu trong VBNA)',g.chapter==='Khách'?'':g.chapter||'')}${area('giProducts','Sản phẩm / Dịch vụ đang kinh doanh *',g.products||'')}</div><p>Thông tin dùng để liên hệ và chuẩn bị buổi họp. Vui lòng xác nhận khách đồng ý cung cấp thông tin.</p><button class="btn btn-wine">Lưu đăng ký khách mời</button></form>`)};
window.saveGuestIntakeV7=(e,id)=>{e.preventDefault();if(!canGuestIntakeV7())return toast('Bạn không có quyền nhập khách mời');const meeting=S.meetings.find(m=>m.id===val('giMeeting'));if(!meeting||meeting.deletedAt||['closed','cancelled'].includes(meeting.status))return toast('Chọn buổi họp chưa đóng');if(!requireName(val('giName')))return;const phone=val('giPhone').replace(/[\s.()-]/g,'');if(!/^\+?\d{9,15}$/.test(phone))return toast('Nhập số điện thoại hợp lệ');if(!val('giIndustry').trim()||!val('giProducts').trim())return toast('Nhập ngành nghề và sản phẩm / dịch vụ');if(S.guests.some(g=>g.id!==id&&g.phone.replace(/[\s.()-]/g,'')===phone))return toast('Khách đã có trong danh sách. Hãy chọn Cập nhật để bổ sung buổi họp.');const before=structuredClone(S.guests),g=S.guests.find(g=>g.id===id);if(id&&!g)return toast('Không tìm thấy khách mời');const data={fullName:normalizeName(val('giName')),phone,email:val('giEmail').trim(),address:val('giAddress').trim(),dob:val('giDob'),businessType:val('giType'),company:val('giCompany').trim(),industry:val('giIndustry').trim(),products:val('giProducts').trim(),inviterId:val('giInviter')||null,guestCategory:val('giCategory'),chapter:val('giCategory')==='guest_external'?'Khách':val('giChapter'),meetingId:meeting.id,meetingIds:[...new Set([...(g?.meetingIds||[]),g?.meetingId,meeting.id].filter(Boolean))],updatedBy:currentUser().id,updatedAt:iso()};if(g)Object.assign(g,data);else S.guests.push({id:uid('G'),status:'new',createdAt:iso(),createdBy:currentUser().id,source:'guest_board',...data});try{save()}catch(err){S.guests=before;return toast('Không lưu được khách mời: '+err.message)}closeModal();refreshGuestIntakeV7();toast('Đã lưu đăng ký, chưa điểm danh','success')};
const departmentBeforeIntakeV7=renderDepartmentsV6;renderDepartmentsV6=function(){departmentBeforeIntakeV7();mountGuestIntakeV7()};const workspaceBeforeIntakeV7=renderRoleWorkspaceV7;renderRoleWorkspaceV7=function(feature){workspaceBeforeIntakeV7(feature);mountGuestIntakeV7()};

function refreshPostsV7(){if(document.body.dataset.page==='finance')renderFinanceV6();else if(document.body.dataset.page==='role-workspace')renderRoleWorkspaceV7(new URLSearchParams(location.search).get('view'));else renderDepartmentsV6()}
window.editPostV7=id=>{const p=S.posts.find(p=>p.id===id&&!p.deletedAt);if(!p||!canDept(p.department))return toast('Bạn không có quyền sửa bản tin');postForm(p.department);const form=q('#poTitle').closest('form');form.onsubmit=e=>savePostEditV7(e,id);q('#poTitle').value=p.title;q('#poBody').value=p.body;q('#poScope').value=p.scope;q('#poImportant').checked=!!p.important;if(q('#poSponsor'))q('#poSponsor').checked=!!p.sponsorship;qa('.postAudience').forEach(el=>el.checked=(p.audience||[]).includes(el.value));form.querySelector('button').textContent=canLead()?'Lưu thay đổi':'Gửi lại phê duyệt';q('#poFile').insertAdjacentHTML('afterend',`<p class="small-text">${p.file?'Đang có tệp đính kèm. Chọn tệp mới để thay thế; để trống để giữ tệp cũ.':'Có thể bổ sung tệp đính kèm.'}</p>`)};
window.savePostEditV7=async(e,id)=>{e.preventDefault();const p=S.posts.find(p=>p.id===id&&!p.deletedAt);if(!p||!canDept(p.department))return toast('Bạn không có quyền sửa bản tin');const title=val('poTitle').trim(),body=val('poBody').trim(),audience=qa('.postAudience:checked').map(el=>el.value);if(!title||!body||!audience.length)return toast('Nhập tiêu đề, nội dung và chọn đối tượng nhận');if(e.target.dataset.saving)return;e.target.dataset.saving='1';const before=structuredClone(p),approvals=structuredClone(S.approvals);try{const files=await persistInputFiles(q('#poFile'),1,'announcement');Object.assign(p,{title,body,audience,scope:p.department==='orientation'?'internal':val('poScope'),important:!!q('#poImportant').checked,file:files[0]||p.file,status:canLead()?'approved':'pending',updatedBy:currentUser().id,updatedAt:iso()});if(q('#poSponsor'))p.sponsorship=q('#poSponsor').checked;S.approvals.filter(a=>a.type==='post'&&a.entityId===id&&a.status==='pending').forEach(a=>a.status='cancelled');if(!canLead())S.approvals.unshift({id:uid('APR'),type:'post',entityId:id,title:'Cập nhật thông báo: '+title,payload:{},status:'pending',requestedBy:currentUser().id,createdAt:iso()});save();closeModal();refreshPostsV7();toast(canLead()?'Đã sửa bản tin':'Đã gửi bản tin sửa đổi chờ duyệt','success')}catch(err){Object.assign(p,before);S.approvals=approvals;toast('Không lưu được bản tin: '+err.message)}finally{delete e.target.dataset.saving}};
window.deletePostV7=id=>{const p=S.posts.find(p=>p.id===id&&!p.deletedAt);if(!p||!canDept(p.department))return toast('Bạn không có quyền xóa bản tin');if(!confirm('Xóa bản tin “'+p.title+'”? Bản tin sẽ không còn hiển thị.'))return;const before=structuredClone(p),approvals=structuredClone(S.approvals);p.deletedAt=iso();p.deletedBy=currentUser().id;p.status='deleted';S.approvals.filter(a=>a.type==='post'&&a.entityId===id&&a.status==='pending').forEach(a=>a.status='cancelled');try{save()}catch(err){delete p.deletedAt;delete p.deletedBy;Object.assign(p,before);S.approvals=approvals;return toast('Không xóa được bản tin: '+err.message)}refreshPostsV7();toast('Đã xóa bản tin','success')};

function canManageTrainingV7(t){return !!currentUser()&&canDept('training')}
function refreshTrainingV7(){if(document.body.dataset.page==='role-workspace')renderRoleWorkspaceV7('training');else renderDepartmentsV6()}
window.editTrainingV7=id=>{const t=S.training.find(t=>t.id===id);if(!t||!canManageTrainingV7(t))return toast('Bạn không có quyền sửa bài đào tạo');trainingForm();const form=q('#trTitle').closest('form');form.onsubmit=e=>saveTrainingEditV7(e,id);for(const [key,value] of Object.entries({trTitle:t.title,trField:t.field,trTrainer:t.trainer,trDate:t.date,trMeeting:t.meetingId,trDescription:t.description}))q('#'+key).value=value||'';form.querySelector('button').textContent='Lưu thay đổi';q('#trFiles').insertAdjacentHTML('afterend',`<p class="small-text">Tài liệu hiện có được giữ lại. Có thể bổ sung, tối đa 10 tệp cho mỗi bài.</p>${(t.files||[]).map((f,i)=>`<label class="inline-check"><input type="checkbox" class="trRemoveV7" value="${i}"> Bỏ tài liệu: ${esc(f.name)}</label>`).join('')}`)};
window.saveTrainingEditV7=async(e,id)=>{e.preventDefault();const t=S.training.find(t=>t.id===id);if(!t||!canManageTrainingV7(t))return toast('Bạn không có quyền sửa bài đào tạo');if(!val('trTitle').trim()||!val('trField').trim()||!val('trTrainer').trim()||!val('trDate'))return toast('Nhập đầy đủ tên bài, lĩnh vực, người đào tạo và ngày');const remove=new Set(qa('.trRemoveV7:checked').map(el=>Number(el.value))),kept=(t.files||[]).filter((_,i)=>!remove.has(i));if(kept.length+q('#trFiles').files.length>10)return toast('Mỗi bài tối đa 10 tài liệu');if(e.target.dataset.saving)return;e.target.dataset.saving='1';const before=structuredClone(t);try{const files=await persistInputFiles(q('#trFiles'),10,'training');Object.assign(t,{title:val('trTitle').trim(),field:val('trField').trim(),trainer:val('trTrainer').trim(),date:val('trDate'),meetingId:val('trMeeting'),description:val('trDescription'),files:[...kept,...files],updatedBy:currentUser().id,updatedAt:iso()});save();closeModal();refreshTrainingV7();toast('Đã cập nhật bài đào tạo','success')}catch(err){S.training[S.training.findIndex(x=>x.id===id)]=before;toast('Không lưu được bài đào tạo: '+err.message)}finally{delete e.target.dataset.saving}};
window.deleteTrainingV7=id=>{const t=S.training.find(t=>t.id===id);if(!t||!canManageTrainingV7(t))return toast('Bạn không có quyền xóa bài đào tạo');if(!confirm('Xóa bài đào tạo “'+t.title+'” cùng bình chọn và góp ý của bài này?'))return;const before=S.training;S.training=S.training.filter(t=>t.id!==id);try{save()}catch(err){S.training=before;return toast('Không xóa được bài đào tạo: '+err.message)}refreshTrainingV7();toast('Đã xóa bài đào tạo','success')};

const reportNamesV7={'Pham vi bao cao':'Phạm vi báo cáo','Tong hop tuan':'Tổng hợp tuần','Diem danh buoi hop':'Điểm danh buổi họp','Tong ket buoi hop':'Tổng kết buổi họp','Khach moi':'Khách mời','CRM':'Danh sách khách mời','Dao tao':'Đào tạo','Truyen thong':'Truyền thông','Power Team':'Power Team','Co hoi':'Cơ hội kinh doanh','Danh gia hoi vien':'Đánh giá hội viên','So quy':'Sổ quỹ','Cong no':'Công nợ','Tai tro':'Tài trợ'};
function reportModeNameV7(mode){return mode==='all'?'Báo cáo tổng hợp Chapter 11':mode==='president'?'Báo cáo điều hành — Chủ tịch':'Báo cáo '+(S.departments.find(d=>d.id===mode)?.name||mode)}
function reportTextV7(v,header){if(typeof v!=='string')return v;const names={approved:'Đã duyệt',pending:'Chờ duyệt',rejected:'Không duyệt',cancelled:'Đã hủy',deleted:'Đã xóa',new:'Chưa liên hệ',contacted:'Đã liên hệ',unreachable:'Chưa liên hệ được',invited:'Đã mời',declined:'Từ chối tham gia',attended:'Đã tham dự',interested:'Quan tâm',application:'Đang làm hồ sơ',success:'Thành công',failed:'Không thành công',internal:'Nội bộ',public:'Công khai và nội bộ',guest_external:'Khách ngoài VBNA',guest_vbna:'Khách trong VBNA',guest_internal:'Khách trong VBNA',chapter_president:'Chủ tịch Chapter',all:'Toàn bộ hội viên',lt:'Ban lãnh đạo'};if(['Ban','Đối tượng'].includes(header))return v.split(', ').map(x=>S.departments.find(d=>d.id===x)?.name||names[x]||x).join(', ');if(['Trạng thái','Phân loại','Phạm vi'].includes(header))return names[v]||v;return v}
function reportBundleV7(mode){if(!reportAllowed(mode))throw Error('Bạn không có quyền xuất báo cáo này');const dates=q('#reportFrom')?selectedDates():{from:S.config.term.start,to:S.config.term.end};const raw=reportDatasets(mode),title=reportModeNameV7(mode),meta={title,period:`Kỳ báo cáo: ${fmtDate(dates.from)} – ${fmtDate(dates.to)}`,prepared:`Người lập: ${userName(currentUser()?.id)} · Ngày lập: ${fmtDate(localDay())}`,term:S.config.term.name};const sheets=raw.map(d=>({...d,name:reportNamesV7[d.name]||d.name,report:meta,rows:d.rows.map(row=>row.map((v,c)=>d.name==='Pham vi bao cao'&&row[0]==='Phân hệ'&&c===1?title:reportTextV7(v,d.headers[c])))}));const summary=sheets.filter(d=>d.name!=='Phạm vi báo cáo').map(d=>[d.name,d.rows.length]);sheets.unshift({name:'Tóm tắt báo cáo',headers:['Hạng mục báo cáo','Số dòng chi tiết'],rows:summary,report:meta});return {meta,sheets}}
function reportCellV7(v,percent){if(typeof v==='number')return percent?(v*100).toLocaleString('vi-VN',{maximumFractionDigits:2})+'%':v.toLocaleString('vi-VN');if(typeof v==='string'&&/^\d{4}-\d{2}-\d{2}(T|$)/.test(v))return v.includes('T')?fmtDT(v):fmtDate(v);return v??''}
function reportDocumentV7(bundle){const {meta,sheets}=bundle;const sections=sheets.flatMap(s=>{const groups=[];if(s.headers.length<=8)groups.push(s.headers.map((_,i)=>i));else for(let start=2;start<s.headers.length;start+=6)groups.push([0,1,...s.headers.map((_,i)=>i).slice(start,start+6)]);return groups.map((cols,gi)=>`<section class="sheet"><header><div class="brand">VBNA CHAPTER 11</div><h1>${esc(meta.title)}</h1><p>${esc(meta.term)} · ${esc(meta.period)}</p><p>${esc(meta.prepared)}</p></header><h2>${esc(s.name)}${groups.length>1?' — Phần '+(gi+1)+'/'+groups.length:''}</h2><p class="count">${s.rows.length} dòng dữ liệu${s.name==='Sổ quỹ'?' · Đơn vị tiền: VNĐ':''}</p><table><thead><tr>${cols.map(c=>`<th>${esc(s.headers[c])}</th>`).join('')}</tr></thead><tbody>${s.rows.length?s.rows.map(r=>`<tr>${cols.map(c=>`<td class="${typeof r[c]==='number'?'num':''}">${esc(reportCellV7(r[c],s.percentColumns?.includes(c)))}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${cols.length}">Không có dữ liệu trong kỳ báo cáo.</td></tr>`}</tbody></table><footer>VBNA Chapter 11 · ${esc(s.name)} · Nguồn: dữ liệu hệ thống tại thời điểm lập báo cáo</footer></section>`)}).join('');return `<!doctype html><html lang="vi"><head><meta charset="utf-8"><title>${esc(meta.title)}</title><style>@page{size:A4 landscape;margin:14mm}*{box-sizing:border-box}body{font:11pt Arial,sans-serif;color:#292321;margin:0;background:#eee}.tools{padding:16px;text-align:center}button{padding:12px 24px;background:#9c0001;color:white;border:1px solid #c9a34b;border-radius:6px;cursor:pointer}.sheet{background:#fff;max-width:1120px;margin:20px auto;padding:32px;border:1px solid #c9a34b;break-before:page}header{border-bottom:2px solid #b89340;padding-bottom:12px;margin-bottom:20px}.brand{font-weight:bold;color:#9c0001;letter-spacing:1px}h1{font-size:21pt;margin:12px 0}h2{font-size:15pt;color:#9c0001;margin:16px 0 8px}p{margin:6px 0;font-size:10pt}.count{color:#666}table{border-collapse:collapse;width:100%;table-layout:fixed;font-size:9pt}thead{display:table-header-group}th,td{border:1px solid #b6a889;padding:8px;vertical-align:top;overflow-wrap:anywhere;line-height:1.4}th{background:#9c0001;color:#fff;text-align:left}tbody tr:nth-child(even){background:#fff7e8}tr{break-inside:avoid}.num{text-align:right;font-variant-numeric:tabular-nums}footer{margin-top:16px;padding-top:8px;border-top:1px solid #c9a34b;color:#665b49;font-size:8pt}@media print{body{background:white}.tools{display:none}.sheet{max-width:none;margin:0;padding:0;border:0}.sheet:first-of-type{break-before:auto}*{print-color-adjust:exact;-webkit-print-color-adjust:exact}}</style></head><body><div class="tools"><button onclick="window.print()">In báo cáo / Lưu PDF</button></div>${sections}</body></html>`}
window.printReportV7=(mode)=>{try{const bundle=reportBundleV7(mode||allowedReportMode()),w=window.open('','_blank');if(!w)return toast('Cho phép mở cửa sổ mới để xem bản in báo cáo');w.document.write(reportDocumentV7(bundle));w.document.close()}catch(err){toast(err.message)}};
window.exportV6Report=async mode=>{try{mode=mode||allowedReportMode();const {sheets}=reportBundleV7(mode);await exportXlsx(sheets,'VBNA_Chapter11_'+mode+'_'+localDay()+'.xlsx')}catch(err){toast(err.message)}};
window.refreshReportView=()=>{try{const {meta,sheets}=reportBundleV7(allowedReportMode());q('#reportOutput').innerHTML=`<section class="panel"><h2>${esc(meta.title)}</h2><p>${esc(meta.period)}</p><p>${esc(meta.prepared)}</p></section>`+sheets.map(d=>`<section class="panel report-block"><h2 class="report-title">${esc(d.name)}</h2>${table(d.headers,d.rows.map(r=>r.map((v,c)=>esc(reportCellV7(v,d.percentColumns?.includes(c))))))}</section>`).join('')}catch(err){toast(err.message)}};
function ledgerBundleV7(){if(!financeAccess())throw Error('Bạn không có quyền xem sổ quỹ');const f=financeFilterV7,l=C11Finance.ledger(S,f),meta={title:'Báo cáo Ban Thư ký — Sổ quỹ',term:S.config.term.name,period:`Kỳ báo cáo: ${f.from?fmtDate(f.from):'Từ đầu dữ liệu'} – ${f.to?fmtDate(f.to):'Đến hiện tại'} · Quỹ: ${f.method||'Tất cả'}`,prepared:`Người lập: ${userName(currentUser()?.id)} · Ngày lập: ${fmtDate(localDay())}`};const sheets=[{name:'Tổng hợp thu chi',headers:['Quỹ','Số dư đầu kỳ','Tổng thu','Tổng chi','Số dư cuối kỳ'],rows:l.summary.map(x=>[x.method,x.opening,x.income,x.expense,x.closing])},{name:'Sổ quỹ chi tiết',headers:['Mã phiếu','Ngày','Diễn giải','Quỹ','Thu','Chi','Cộng dồn tiền mặt','Cộng dồn chuyển khoản','Chưa phân loại','Tổng số dư'],rows:[['Đầu kỳ','','','','','',l.start['Tiền mặt'],l.start['Chuyển khoản'],l.start['Chưa phân loại'],Object.values(l.start).reduce((a,b)=>a+b,0)],...l.rows.map(x=>[x.id,x.date,x.description,x.fund,x.kind==='income'?x.amount:0,x.kind==='expense'?x.amount:0,x.cash,x.bank,x.unknown,x.balance]),['Cuối kỳ','','','','','',l.closing['Tiền mặt'],l.closing['Chuyển khoản'],l.closing['Chưa phân loại'],Object.values(l.closing).reduce((a,b)=>a+b,0)]]}];sheets[0].rows.push(['Tổng cộng',...['opening','income','expense','closing'].map(k=>l.summary.reduce((n,x)=>n+x[k],0))]);return {meta,sheets:sheets.map(s=>({...s,report:meta}))}}
window.printLedgerReportV7=()=>{try{const bundle=ledgerBundleV7(),w=window.open('','_blank');if(!w)return toast('Cho phép mở cửa sổ mới để xem bản in');w.document.write(reportDocumentV7(bundle));w.document.close()}catch(e){toast(e.message)}};
window.exportLedgerReportV7=async()=>{try{await exportXlsx(ledgerBundleV7().sheets,'VBNA_C11_So_quy_'+localDay()+'.xlsx')}catch(e){toast(e.message)}};

function canMeetingsV7(){return ['admin','president','vice_president','event_lead','event_member'].includes(currentUser()?.role)}
function meetingsWorkspaceV7(){return `<div class="toolbar"><h2>Danh sách cuộc họp</h2>${canMeetingsV7()?button('Tạo cuộc họp','addMeeting()'):''}</div>${table(['Cuộc họp','Ngày giờ','Địa điểm','Trạng thái','Số điểm danh','Thao tác'],S.meetings.filter(m=>!m.deletedAt).map(m=>[esc(m.name),fmtDate(m.date)+' · '+esc(m.time),esc(m.location),esc(({open:'Đang hoạt động',closed:'Dừng hoạt động',scheduled:'Đã lên lịch',cancelled:'Đã hủy'})[m.status]||m.status),S.attendance.filter(a=>a.meetingId===m.id).length,`<a class="btn btn-outline btn-sm" href="meeting.html?meeting=${encodeURIComponent(m.id)}">Xem</a>${canMeetingsV7()?button('Sửa',`editMeetingV7('${m.id}')`,'btn-outline btn-sm')+button(m.status==='open'?'Dừng hoạt động':'Mở hoạt động',`setMeetingActivityV7('${m.id}',${m.status!=='open'})`,'btn-outline btn-sm')+button('Xóa',`deleteMeetingV7('${m.id}')`,'btn-outline btn-sm'):''}`]))}`}
function refreshMeetingsV7(){if(document.body.dataset.page==='admin'&&isAdmin())renderMeetings();else renderRoleWorkspaceV7('meetings')}
renderMeetings=function(){const host=q('#meetingsTable')?.closest('.panel');if(host){host.innerHTML=meetingsWorkspaceV7();host.id='meetingListV7'}else if(q('#meetingListV7'))q('#meetingListV7').innerHTML=meetingsWorkspaceV7();const m=activeMeeting();if(q('#attendanceTable'))q('#attendanceTable').innerHTML=S.attendance.filter(a=>a.meetingId===m.id).map(a=>`<tr><td>${esc(a.fullName)}</td><td>${esc(a.role)}</td><td>${esc(a.chapter)}</td><td>${maskPhone(a.phone)}</td><td>${esc(memberName(a.inviterId))}</td><td>${fmtDT(a.checkedAt)}</td></tr>`).join('')};
window.addMeeting=()=>editMeetingV7('');
window.editMeetingV7=id=>{if(!canMeetingsV7())return toast('Bạn không có quyền quản lý cuộc họp');const m=S.meetings.find(m=>m.id===id&&!m.deletedAt)||{};if(id&&!m.id)return;openModal(id?'Sửa cuộc họp':'Tạo cuộc họp',`<form onsubmit="saveMeetingV7(event,'${id}')"><div class="form-grid">${field('mvName','Tên cuộc họp *',m.name||'','text','required')}${field('mvDate','Ngày *',m.date||localDay(),'date','required')}${field('mvTime','Giờ *',m.time||'13:30','time','required')}${field('mvLocation','Địa điểm *',m.location||'Hải Phòng','text','required')}${field('mvWeek','Tuần nhiệm kỳ',m.termWeek||0,'number','min="0" step="1"')}${select('mvType','Loại cuộc họp',[['main','Buổi họp chính'],['event','Sự kiện']],m.type||'main')}${field('mvCutoff','Giờ chốt doanh thu',m.revenueCutoff||'17:00','time','required')}${select('mvStatus','Trạng thái',[['scheduled','Đã lên lịch'],['open','Đang hoạt động'],['closed','Dừng hoạt động']],m.status||'scheduled')}</div><button class="btn btn-wine">Lưu cuộc họp</button></form>`)};
function persistMeetingsV7(before){try{save();return true}catch(e){S.meetings=before;toast('Không lưu được cuộc họp: '+e.message);return false}}
window.saveMeetingV7=(e,id)=>{e.preventDefault();if(!canMeetingsV7())return toast('Bạn không có quyền quản lý cuộc họp');const old=S.meetings.find(m=>m.id===id&&!m.deletedAt);if(id&&!old)return toast('Cuộc họp không còn tồn tại');const name=val('mvName').trim(),date=val('mvDate'),time=val('mvTime'),location=val('mvLocation').trim(),status=val('mvStatus'),week=Number(val('mvWeek'));if(!name||!date||!time||!location||!Number.isInteger(week)||week<0||!['open','closed','scheduled'].includes(status))return toast('Điền đầy đủ thông tin cuộc họp hợp lệ');const before=structuredClone(S.meetings);if(status==='open')S.meetings.forEach(m=>{if(m.id!==id&&m.status==='open')m.status='closed'});const fields={name,date,time,location,termWeek:week,type:val('mvType'),revenueCutoff:val('mvCutoff'),status,updatedBy:currentUser().id,updatedAt:iso()};if(old)Object.assign(old,fields);else S.meetings.push({id:uid('M'),publicCode:uid('C11').slice(0,12),createdBy:currentUser().id,createdAt:iso(),...fields});if(!persistMeetingsV7(before))return;closeModal();refreshMeetingsV7();toast('Đã lưu cuộc họp','success')};
window.saveMeeting=(e)=>saveMeetingV7(e,'');
window.setMeetingActivityV7=(id,open)=>{if(!canMeetingsV7())return toast('Bạn không có quyền quản lý cuộc họp');const m=S.meetings.find(m=>m.id===id&&!m.deletedAt);if(!m)return;const before=structuredClone(S.meetings);if(open)S.meetings.forEach(x=>{if(x.status==='open')x.status='closed'});m.status=open?'open':'closed';m.updatedBy=currentUser().id;m.updatedAt=iso();if(persistMeetingsV7(before))refreshMeetingsV7()};
window.deleteMeetingV7=id=>{if(!canMeetingsV7())return toast('Bạn không có quyền quản lý cuộc họp');const m=S.meetings.find(m=>m.id===id&&!m.deletedAt);if(!m||!confirm('Xóa cuộc họp “'+m.name+'” khỏi danh sách hoạt động? Lịch sử điểm danh và nghiệp vụ liên quan vẫn được giữ.'))return;const before=structuredClone(S.meetings);Object.assign(m,{status:'cancelled',deletedAt:iso(),deletedBy:currentUser().id});if(persistMeetingsV7(before))refreshMeetingsV7()};
const portalMenuBeforeV7=renderPortalV6;renderPortalV6=function(){portalMenuBeforeV7();const nav=q('.d-portal-sidebar');if(nav&&!q('#memberSystemNavV7'))nav.insertAdjacentHTML('beforeend',`<nav id="memberSystemNavV7" aria-label="Menu hệ thống"><h3>Menu hệ thống</h3>${V7_VIEW_FEATURES.filter(([key])=>key!=='personal'&&canViewV7(key)).map(([key,label])=>`<a href="workspace.html?view=${key}">${esc(label)}</a>`).join('')}</nav>`)};
